const TEST_BANK_DWES = [

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 1 — Arquitectura web y protocolos HTTP
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwes_u1_q1", unit:1, question:"¿Qué protocolo usan los navegadores para comunicarse con los servidores web?", options:["FTP, concepto diferente al que se describe en esta pregunta","SMTP, concepto diferente al que se describe en esta pregunta","HTTP/HTTPS","SSH, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"HTTP (HyperText Transfer Protocol) y HTTPS (con TLS/SSL) son los protocolos estándar de transferencia en la web.", noShuffle:false },
  { concept_id:"dwes_u1_q2", unit:1, question:"¿Qué significa el código de estado HTTP 404?", options:["Petición correcta (OK)","Acceso no autorizado","Recurso no encontrado","Error interno del servidor"], correct:2, explanation:"404 Not Found indica que el servidor no ha encontrado el recurso solicitado.", noShuffle:false },
  { concept_id:"dwes_u1_q3", unit:1, question:"¿Cuál es la diferencia fundamental entre los métodos HTTP GET y POST?", options:["GET es cifrado y POST plano, concepto diferente al que se describe en esta pregunta","GET envía los parámetros en la URL (query string) y es idempotente","POST tiene un límite estricto de 2048 caracteres","GET no puede recibir respuestas del servidor, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"GET envía datos en la query string (visible, cacheable, longitud limitada). POST envía en el body, apto para datos sensibles y payloads grandes.", noShuffle:false },
  { concept_id:"dwes_u1_q4", unit:1, question:"¿Qué significa que HTTP es un protocolo 'sin estado' (stateless)?", options:["Que no puede almacenar archivos en disco, concepto diferente al que se describe en esta pregunta","Que cada petición es independiente y el servidor no recuerda peticiones anteriores sin mecanismos adicionales como cookies o sesiones","Que las conexiones no tienen IP de origen, concepto diferente al que se describe en esta pregunta","Que no permite autenticación, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"HTTP es stateless por diseño: no mantiene memoria de transacciones previas. Para gestionar estado se usan Cookies, Sesiones y Tokens.", noShuffle:false },
  { concept_id:"dwes_u1_q5", unit:1, question:"¿Qué código de estado HTTP indica una redirección permanente?", options:["301 Moved Permanently","302 Found","304 Not Modified","307 Temporary Redirect"], correct:0, explanation:"301 indica que el recurso se ha movido permanentemente a una nueva URL, lo cual actualiza índices de motores de búsqueda.", noShuffle:false },
  { concept_id:"dwes_u1_q6", unit:1, question:"¿Qué código HTTP se devuelve típicamente cuando la autenticación ha fallado o falta credencial?", options:["401 Unauthorized","403 Forbidden","400 Bad Request","405 Method Not Allowed"], correct:0, explanation:"401 Unauthorized indica falta de autenticación válida. 403 Forbidden indica que el usuario está autenticado pero no tiene permisos.", noShuffle:false },
  { concept_id:"dwes_u1_q7", unit:1, question:"¿Qué función cumple la cabecera HTTP 'Content-Type'?", options:["Indica el tamaño del archivo, concepto diferente al que se describe en esta pregunta","Especifica el tipo MIME de los datos enviados en el cuerpo de la petición o respuesta","Indica el software del servidor, concepto diferente al que se describe en esta pregunta","Define el tiempo de expiración de la caché, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Content-Type (ej: application/json, text/html) informa al receptor sobre cómo interpretar el payload del cuerpo.", noShuffle:false },
  { concept_id:"dwes_u1_q8", unit:1, question:"¿Cuál es el puerto por defecto para el protocolo HTTPS?", options:["80","8080","443","22"], correct:2, explanation:"El puerto estándar para HTTP es el 80 y para HTTPS (con cifrado TLS) es el 443.", noShuffle:false },
  { concept_id:"dwes_u1_q9", unit:1, question:"¿Qué es un servidor web como Apache o Nginx?", options:["Un sistema gestor de bases de datos, que aunque es una herramienta util, no corresponde a esta definicion","Un software que escucha peticiones HTTP en un puerto y despacha archivos estáticos o pasa la ejecución a un intérprete como PHP","Un compilador de código backend, concepto diferente al que se describe en esta pregunta","Un navegador web automatizado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Un servidor web procesa solicitudes HTTP entrantes y entrega recursos o delega scripts dinámicos a través de FastCGI/FPM.", noShuffle:false },
  { concept_id:"dwes_u1_q10", unit:1, question:"¿Qué significa que un método HTTP sea 'idempotente'?", options:["Que solo se puede ejecutar una vez, concepto diferente al que se describe en esta pregunta","Que ejecutarlo múltiples veces con los mismos parámetros produce el mismo efecto en el servidor que ejecutarlo una sola vez","Que no devuelve ningún dato, concepto diferente al que se describe en esta pregunta","Que requiere autenticación obligatoria, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"GET, PUT, DELETE, HEAD y OPTIONS son idempotentes. POST no lo es, ya que invocarlo varias veces puede crear múltiples recursos.", noShuffle:false },
  { concept_id:"dwes_u1_q11", unit:1, question:"¿Qué código de estado HTTP representa un error interno en el servidor?", options:["400, concepto diferente al que se describe en esta pregunta","404, concepto diferente al que se describe en esta pregunta","500 Internal Server Error","503, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"500 indica una condición inesperada en el servidor que impidió procesar la petición (por ejemplo, excepción no capturada en PHP).", noShuffle:false },
  { concept_id:"dwes_u1_q12", unit:1, question:"¿Qué cabecera HTTP envía el cliente para indicar qué formatos de respuesta puede procesar?", options:["Content-Type","Accept","User-Agent","Host"], correct:1, explanation:"Accept (ej: Accept: application/json) solicita al servidor el formato deseado en la negociación de contenido.", noShuffle:false },
  { concept_id:"dwes_u1_q13", unit:1, question:"¿Qué es el modelo cliente-servidor de 3 capas en desarrollo web?", options:["HTML, CSS y JavaScript, concepto diferente al que se describe en esta pregunta","Cliente (Navegador), Servidor de Aplicaciones (Lógica de negocio/PHP) y Servidor de Base de Datos","Frontend, Backend y Redes, concepto diferente al que se describe en esta pregunta","IP, TCP y HTTP, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las 3 capas clásicas son: Capa de Presentación (cliente), Capa de Negocio (servidor web/app) y Capa de Datos (SGBD).", noShuffle:false },
  { concept_id:"dwes_u1_q14", unit:1, question:"¿Qué indica el código HTTP 201 Created?", options:["Petición recibida pero no procesada, concepto diferente al que se describe en esta pregunta","Petición exitosa que ha dado lugar a la creación de un nuevo recurso","Recurso modificado con éxito, concepto diferente al que se describe en esta pregunta","Petición en cola de ejecución, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"201 Created se devuelve habitualmente tras un POST exitoso que crea una nueva entidad, a menudo con la cabecera Location.", noShuffle:false },
  { concept_id:"dwes_u1_q15", unit:1, question:"¿Qué es PHP-FPM (FastCGI Process Manager)?", options:["Un plugin de jQuery para PHP, concepto diferente al que se describe en esta pregunta","Un gestor avanzado de procesos FastCGI para servir PHP de alto rendimiento con servidores como Nginx o Apache","Un compilador estático de PHP a binario C++, concepto diferente al que se describe en esta pregunta","Un framework MVC para PHP, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"PHP-FPM gestiona pools de workers que interpretan scripts PHP de forma aislada y eficiente mediante el protocolo FastCGI.", noShuffle:false },
  { concept_id:"dwes_u1_q16", unit:1, question:"¿Qué diferencia a HTTP/2 de HTTP/1.1?", options:["HTTP/2 no soporta HTTPS, concepto diferente al que se describe en esta pregunta","HTTP/2 usa formato binario, multiplexación sobre una sola conexión TCP","HTTP/2 ya no usa métodos GET o POST, concepto diferente al que se describe en esta pregunta","HTTP/2 requiere obligatoriamente UDP, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"HTTP/2 mejora el rendimiento al multiplexar múltiples peticiones/respuestas simultáneamente en un único socket TCP.", noShuffle:false },
  { concept_id:"dwes_u1_q17", unit:1, question:"¿Qué función cumple la cabecera 'Host' en una petición HTTP/1.1?", options:["Identifica la dirección física MAC del cliente, concepto diferente al que se describe en esta pregunta","Permite el alojamiento virtual (Virtual Hosting) indicando a qué dominio se dirige la petición en un servidor con una sola IP","Configura el cortafuegos del servidor, concepto diferente al que se describe en esta pregunta","Especifica el puerto del cliente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Host es obligatoria en HTTP/1.1 para que un mismo servidor físico con una IP pueda albergar múltiples sitios web (vhosts).", noShuffle:false },
  { concept_id:"dwes_u1_q18", unit:1, question:"¿Qué código HTTP se devuelve cuando el servidor no soporta el método solicitado?", options:["400, concepto diferente al que se describe en esta pregunta","404, concepto diferente al que se describe en esta pregunta","405 Method Not Allowed","501, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"405 Method Not Allowed indica que el recurso existe pero no acepta el método HTTP enviado (ej: un POST a un recurso de solo lectura GET).", noShuffle:false },
  { concept_id:"dwes_u1_q19", unit:1, question:"¿Qué es un Reverse Proxy (Proxy Inverso)?", options:["Un navegador que guarda caché local, concepto diferente al que se describe en esta pregunta","Un servidor intermediario colocado frente a los servidores web que distribuye carga, gestiona TLS y cachea respuestas","Un tipo de cable de red, concepto diferente al que se describe en esta pregunta","Un módulo de autenticación de clientes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Nginx o HAProxy actúan frecuentemente como proxies inversos para balanceo de carga, terminación SSL y protección de los servidores de backend.", noShuffle:false },
  { concept_id:"dwes_u1_q20", unit:1, question:"¿Qué cabecera HTTP previene que una web sea cargada dentro de un iframe (mitigando Clickjacking)?", options:["X-Frame-Options o Content-Security-Policy con frame-ancestors","Access-Control-Allow-Origin, concepto diferente al que se describe en esta pregunta","X-XSS-Protection, concepto diferente al que se describe en esta pregunta","Strict-Transport-Security, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"X-Frame-Options: DENY / SAMEORIGIN impide que un atacante incruste el sitio en un marco transparente para engañar al usuario.", noShuffle:false },
  { concept_id:"dwes_u1_q21", unit:1, question:"¿Qué representa el código de estado HTTP 204 No Content?", options:["Error porque no hay datos disponibles, concepto diferente al que se describe en esta pregunta","La petición se procesó con éxito pero la respuesta intencionadamente no incluye cuerpo (body)","El archivo solicitado está vacío en disco, concepto diferente al que se describe en esta pregunta","El usuario canceló la descarga, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"204 se usa a menudo tras operaciones DELETE o PUT exitosas donde no es necesario devolver datos adicionales.", noShuffle:false },
  { concept_id:"dwes_u1_q22", unit:1, question:"¿Qué significa el acrónimo LAMP?", options:["Linux, Apache, MySQL, PHP","Lighttpd, Android, Mongo, Python","Linux, Angular, MariaDB, Perl","Localhost, Apache, Memcached, PHP"], correct:0, explanation:"LAMP es el stack tradicional de código abierto más popular para el desarrollo y despliegue web en servidor.", noShuffle:false },
  { concept_id:"dwes_u1_q23", unit:1, question:"¿Qué protocolo de transporte utiliza HTTP/3?", options:["TCP, concepto diferente al que se describe en esta pregunta","UDP (a través del protocolo QUIC)","SCTP, concepto diferente al que se describe en esta pregunta","ICMP, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"HTTP/3 sustituye TCP por QUIC sobre UDP, reduciendo la latencia de establecimiento de conexión y eliminando el bloqueo 'head-of-line'.", noShuffle:false },
  { concept_id:"dwes_u1_q24", unit:1, question:"¿Qué cabecera HTTP se utiliza para transmitir credenciales de autenticación básica o tokens Bearer?", options:["Proxy-Authenticate","Authorization","Credentials","Authentication"], correct:1, explanation:"La cabecera 'Authorization: Bearer <token>' o 'Authorization: Basic <base64>' transporta credenciales seguras al servidor.", noShuffle:false },
  { concept_id:"dwes_u1_q25", unit:1, question:"¿Qué código HTTP se envía al cliente cuando un recurso no ha cambiado y se debe usar la copia en caché?", options:["200 OK","301 Moved","304 Not Modified","412 Precondition Failed"], correct:2, explanation:"304 Not Modified se devuelve si las cabeceras If-Modified-Since o ETag coinciden con la versión actual del servidor.", noShuffle:false },
  { concept_id:"dwes_u1_q26", unit:1, question:"¿Qué es un archivo .htaccess en servidores Apache?", options:["Un script ejecutable de PHP, concepto diferente al que se describe en esta pregunta","Un archivo de configuración a nivel de directorio para reescritura de URLs, autenticación y cabeceras","Un certificado de seguridad, concepto diferente al que se describe en esta pregunta","Una clave privada, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:".htaccess permite sobreescribir directivas de Apache en carpetas locales, como habilitar mod_rewrite para URLs amigables.", noShuffle:false },
  { concept_id:"dwes_u1_q27", unit:1, question:"¿Qué diferencia hay entre el método PUT y el método PATCH en HTTP?", options:["Son idénticos y sinónimos, concepto diferente al que se describe en esta pregunta","PUT reemplaza completamente el recurso; PATCH aplica modificaciones parciales","PATCH crea recursos nuevos y PUT los elimina, concepto diferente al que se describe en esta pregunta","PUT no es idempotente y PATCH sí, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Según la especificación HTTP, PUT envía la representación completa para sustituir la entidad; PATCH solo envía los campos a actualizar.", noShuffle:false },
  { concept_id:"dwes_u1_q28", unit:1, question:"¿Qué significa el código HTTP 429 Too Many Requests?", options:["El tamaño de la petición excede el límite, concepto que se aplica en un contexto distinto","El cliente ha superado el límite de peticiones permitido en un intervalo de tiempo (Rate Limiting)","El servidor tiene sobrecarga de CPU, concepto diferente al que se describe en esta pregunta","Petición con cabeceras duplicadas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"429 es el código estándar para indicar que el cliente está siendo restringido por un mecanismo de control de tasa (rate limiter).", noShuffle:false },
  { concept_id:"dwes_u1_q29", unit:1, question:"¿Qué utilidad tiene la cabecera ETag en HTTP?", options:["Codificar caracteres especiales, concepto diferente al que se describe en esta pregunta","Un identificador único de versión del recurso que permite validación condicional de caché eficiente","Indicar la duración de la sesión, concepto diferente al que se describe en esta pregunta","Fijar cookies, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"ETag es un hash o token generado por el servidor para verificar si el contenido cambió sin retransmitir todo el archivo.", noShuffle:false },
  { concept_id:"dwes_u1_q30", unit:1, question:"¿Qué directiva de Nginx pasa peticiones dinámicas a PHP-FPM?", options:["proxy_pass","fastcgi_pass","php_include","cgi_exec"], correct:1, explanation:"fastcgi_pass (ej: fastcgi_pass unix:/var/run/php/php8.2-fpm.sock;) redirige scripts PHP al worker pool de FastCGI.", noShuffle:false },
  { concept_id:"dwes_u1_q31", unit:1, question:"¿Qué es el 'handshake' TLS en una conexión HTTPS?", options:["Un intercambio inicial donde cliente y servidor negocian cifrado","La compresión de los paquetes TCP, concepto que se aplica en un contexto distinto","La resolución DNS del dominio, concepto diferente al que se describe en esta pregunta","El login del usuario, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"El TLS handshake asegura la confidencialidad e integridad del canal mediante criptografía asimétrica y claves de sesión simétricas.", noShuffle:false },
  { concept_id:"dwes_u1_q32", unit:1, question:"¿Qué código de estado indica que el servidor actúa como pasarela y no recibió respuesta a tiempo del backend?", options:["500","502 Bad Gateway","504 Gateway Timeout","408 Request Timeout"], correct:2, explanation:"504 Gateway Timeout ocurre cuando el proxy (ej: Nginx) agota el tiempo de espera esperando la respuesta del proceso PHP o BD.", noShuffle:false },
  { concept_id:"dwes_u1_q33", unit:1, question:"¿Qué código HTTP devuelve el proxy si el servidor backend está caído o rechaza la conexión?", options:["502 Bad Gateway","503 Service Unavailable","500 Internal Server Error","404 Not Found"], correct:0, explanation:"502 Bad Gateway significa que el proxy inverso recibió una respuesta inválida o no pudo conectar con el servidor upstream (ej: PHP-FPM parado).", noShuffle:false },
  { concept_id:"dwes_u1_q34", unit:1, question:"¿Qué tipo de MIME se utiliza al subir archivos mediante formularios HTML?", options:["application/x-www-form-urlencoded","text/plain","multipart/form-data","application/octet-stream"], correct:2, explanation:"multipart/form-data divide los campos y archivos binarios en bloques delimitados por un 'boundary' en el cuerpo de la petición.", noShuffle:false },
  { concept_id:"dwes_u1_q35", unit:1, question:"¿Cuál es la función de la cabecera Strict-Transport-Security (HSTS)?", options:["Prohibir peticiones POST, concepto diferente al que se describe en esta pregunta","Obligar al navegador a comunicarse exclusivamente a través de HTTPS durante el tiempo especificado","Bloquear scripts no firmados, concepto diferente al que se describe en esta pregunta","Exigir contraseña en cada petición, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"HSTS previene ataques Man-in-the-Middle y SSL Stripping obligando a que toda conexión futura use HTTPS sin posibilidad de degradar a HTTP.", noShuffle:false },
  { concept_id:"dwes_u1_q36", unit:1, question:"¿Qué método HTTP se utiliza típicamente para consultar las opciones de comunicación permitidas para un recurso (preflight en CORS)?", options:["HEAD","TRACE","OPTIONS","CONNECT"], correct:2, explanation:"OPTIONS permite al cliente averiguar los métodos, cabeceras y orígenes permitidos por el servidor antes de realizar una petición compleja con CORS.", noShuffle:false },
  { concept_id:"dwes_u1_q37", unit:1, question:"¿Qué es el 'Keep-Alive' en HTTP?", options:["Una señal de comprobación de fallos de hardware, concepto diferente al que se describe en esta pregunta","Un mecanismo que permite reutilizar la misma conexión TCP para múltiples peticiones consecutivas, ahorrando sobrecarga de red","Un bucle infinito de scripts en PHP, concepto diferente al que se describe en esta pregunta","Una cookie que no expira, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Connection: keep-alive evita la penalización de crear y destruir sockets TCP para cada recurso individual (imágenes, CSS, scripts).", noShuffle:false },
  { concept_id:"dwes_u1_q38", unit:1, question:"¿Qué describe la cabecera 'Location' en una respuesta HTTP 302 o 201?", options:["La ubicación geográfica del servidor, concepto diferente al que se describe en esta pregunta","La URL a la que se debe redirigir el cliente o la dirección del nuevo recurso recién creado","El directorio físico en el disco duro, concepto diferente al que se describe en esta pregunta","La IP de la pasarela, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Location indica la nueva URL de redirección en respuestas 3xx o el URI del recurso generado en respuestas 201.", noShuffle:false },
  { concept_id:"dwes_u1_q39", unit:1, question:"¿En qué capa del modelo OSI opera el protocolo HTTP?", options:["Capa de Enlace (Capa 2)","Capa de Red (Capa 3)","Capa de Transporte (Capa 4)","Capa de Aplicación (Capa 7)"], correct:3, explanation:"HTTP opera en el nivel superior (Capa 7 de Aplicación), apoyándose en la Capa de Transporte (TCP/UDP).", noShuffle:false },
  { concept_id:"dwes_u1_q40", unit:1, question:"¿Cuál es la diferencia entre un código 401 y un 403?", options:["401 es error del servidor y 403 del cliente, concepto diferente al que se describe en esta pregunta","401 significa que no se aportaron credenciales válidas; 403 significa que el servidor reconoce la identidad pero deniega el acceso expresamente","401 es para páginas estáticas y 403 para dinámicas, concepto diferente al que se describe en esta pregunta","Son completamente sinónimos en HTTP, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"401 (Unauthenticated): ¿Quién eres? Identifícate. 403 (Unauthorized / Forbidden): Sé quién eres, pero no tienes permiso para esta acción.", noShuffle:false },
  { concept_id:"dwes_u1_q41", unit:1, question:"¿Qué directiva de Apache activa el módulo para reescribir URLs amigables?", options:["RewriteEngine On","EnableFriendlyUrls true","ModUrl active","VirtualHost rewrite"], correct:0, explanation:"'RewriteEngine On' es la directiva que habilita el motor de reescritura de mod_rewrite en la configuración de Apache o .htaccess.", noShuffle:false },
  { concept_id:"dwes_u1_q42", unit:1, question:"¿Qué código de estado HTTP se debe devolver si el cliente envía datos JSON con sintaxis rota o campos inválidos?", options:["500 Internal Error, concepto diferente al que se describe en esta pregunta","400 Bad Request o 422 Unprocessable Entity","404 Not Found, concepto diferente al que se describe en esta pregunta","415 Unsupported Media, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"400 indica petición malformada sintácticamente, y 422 se usa frecuentemente cuando la sintaxis es correcta pero falla la validación de negocio.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 2 — PHP: Fundamentos del lenguaje
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwes_u2_q1", unit:2, question:"¿Dónde se ejecuta el código PHP?", options:["En el navegador del cliente","En el servidor web","En la memoria gráfica","En el switch de red"], correct:1, explanation:"PHP es un lenguaje de script interpretado en el servidor; el cliente únicamente recibe la respuesta procesada (habitualmente HTML o JSON).", noShuffle:false },
  { concept_id:"dwes_u2_q2", unit:2, question:"¿Con qué etiquetas se delimita el código PHP estándar?", options:["<php> ... </php>","<!-- php -->","<?php ... ?>","<% ... %>"], correct:2, explanation:"Las etiquetas estándar y recomendadas por PSR son <?php y ?>. La etiqueta de cierre se debe omitir si el archivo solo contiene PHP.", noShuffle:false },
  { concept_id:"dwes_u2_q3", unit:2, question:"¿Cómo se declaran las variables en PHP?", options:["var nombre = 'Ana';","let $nombre = 'Ana';","$nombre = 'Ana';","dim nombre as string;"], correct:2, explanation:"En PHP todas las variables inician obligatoriamente con el signo de dólar ($) seguido de una letra o guion bajo.", noShuffle:false },
  { concept_id:"dwes_u2_q4", unit:2, question:"¿Qué operador se utiliza para concatenar cadenas de texto en PHP?", options:["+, concepto diferente al que se describe en esta pregunta","&, concepto diferente al que se describe en esta pregunta",". (el punto)",",, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"El punto (.) es el operador de concatenación en PHP: $frase = 'Hola ' . $nombre. El operador + solo realiza suma aritmética.", noShuffle:false },
  { concept_id:"dwes_u2_q5", unit:2, question:"¿Cuál es la diferencia entre comillas dobles y comillas simples al declarar cadenas en PHP?", options:["No hay ninguna diferencia, aunque algunos enfoques establecen matices al respecto","Las comillas dobles interpretan secuencias de escape y variables interpoladas ($var); las comillas simples tratan el texto como literal","Las comillas simples son más lentas, concepto diferente al que se describe en esta pregunta","Las comillas dobles no admiten espacios, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"En comillas dobles \"Hola $usuario\\n\" la variable se sustituye por su valor. En comillas simples '$usuario' se imprime tal cual.", noShuffle:false },
  { concept_id:"dwes_u2_q6", unit:2, question:"¿Qué función se utiliza para imprimir texto de forma sencilla en PHP?", options:["echo o print","System.out.print()","console.log()","write()"], correct:0, explanation:"'echo' y 'print' son construcciones del lenguaje para enviar texto al buffer de salida. 'echo' puede recibir múltiples argumentos separados por coma.", noShuffle:false },
  { concept_id:"dwes_u2_q7", unit:2, question:"¿Cuál es la diferencia entre 'include' y 'require' en PHP?", options:["include es para archivos remotos y require para locales","Si el archivo no existe, include emite un warning y continúa la ejecución","Son perfectamente intercambiables, concepto diferente al que se describe en esta pregunta","require solo funciona con clases, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"require es estricto: aborta la ejecución con un Fatal Error si no encuentra el archivo. include solo genera un Warning (E_WARNING).", noShuffle:false },
  { concept_id:"dwes_u2_q8", unit:2, question:"¿Qué ventaja ofrecen 'require_once' e 'include_once'?", options:["Hacen que el código se ejecute más rápido","Garantizan que el archivo solo se incluya una única vez","Compilan el archivo en memoria permanente","Cifran el archivo incluido, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Evitan el error 'Cannot redeclare function/class' impidiendo inclusiones redundantes en árboles de dependencias complejos.", noShuffle:false },
  { concept_id:"dwes_u2_q9", unit:2, question:"¿Cómo se define una constante en PHP?", options:["constant MI_CONST = 10;, concepto diferente al que se describe en esta pregunta","const MI_CONST = 10; o define('MI_CONST', 10);","$MI_CONST = 10; readonly;, concepto diferente al que se describe en esta pregunta","let const MI_CONST = 10;, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Se definen con la palabra clave 'const' (en tiempo de compilación/clases) o con la función 'define()' (en tiempo de ejecución). No llevan signo $.", noShuffle:false },
  { concept_id:"dwes_u2_q10", unit:2, question:"¿Cuál es la diferencia entre los operadores == y === en PHP?", options:["== es asignación y === comparación, concepto diferente al que se describe en esta pregunta","== compara valores convirtiendo tipos (coerción implícita)","=== solo sirve para objetos, concepto diferente al que se describe en esta pregunta","== es más rápido que ===, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"=== (idéntico) comprueba que tanto el tipo de dato como el contenido coincidan, evitando sorpresas como ('123' == 123 siendo true).", noShuffle:false },
  { concept_id:"dwes_u2_q11", unit:2, question:"¿Qué hace la función isset() en PHP?", options:["Comprueba si una variable tiene valor mayor que cero","Determina si una variable está declarada y su valor no es null","Borra una variable de memoria","Verifica si una cadena es válida"], correct:1, explanation:"isset($var) devuelve true únicamente si la variable existe en el ámbito actual y su contenido no es null.", noShuffle:false },
  { concept_id:"dwes_u2_q12", unit:2, question:"¿Qué evalúa la función empty() en PHP?", options:["Si un archivo está en blanco, concepto diferente al que se describe en esta pregunta","Si una variable no existe o su valor se considera vacío: false, 0, 0.0","Solo si un string tiene longitud cero, concepto diferente al que se describe en esta pregunta","Si una base de datos está sin tablas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"empty() devuelve true para cualquier valor falsy o variable no definida sin generar warnings.", noShuffle:false },
  { concept_id:"dwes_u2_q13", unit:2, question:"¿Qué operador introducido en PHP 7 se conoce como 'Null Coalescing Operator'?", options:["?:","??","<=>","?->"], correct:1, explanation:"$a = $b ?? 'defecto'; equivale a isset($b) ? $b : 'defecto'. Evita comprobar isset() manualmente.", noShuffle:false },
  { concept_id:"dwes_u2_q14", unit:2, question:"¿Qué devuelve el operador 'nave espacial' (<=>) en PHP?", options:["Un booleano true/false, concepto diferente al que se describe en esta pregunta","0 si son iguales, -1 si el de la izquierda es menor, y 1 si el de la izquierda es mayor","La distancia euclídea entre números, concepto diferente al que se describe en esta pregunta","El mayor de los dos operandos, concepto que se aplica en un contexto distinto"], correct:1, explanation:"$a <=> $b devuelve -1, 0 o 1. Es especialmente útil en funciones de ordenación personalizadas con usort().", noShuffle:false },
  { concept_id:"dwes_u2_q15", unit:2, question:"¿Cómo se destruye o elimina una variable de memoria en PHP?", options:["delete($var);","unset($var);","remove($var);","clear($var);"], correct:1, explanation:"unset() destruye las variables especificadas liberando su referencia en memoria.", noShuffle:false },
  { concept_id:"dwes_u2_q16", unit:2, question:"¿Qué directiva del archivo php.ini determina si se muestran los errores en pantalla?", options:["error_reporting","display_errors","log_errors","show_warnings"], correct:1, explanation:"display_errors = On se usa en desarrollo. En producción debe estar a Off por seguridad, enviando los errores a un log con log_errors = On.", noShuffle:false },
  { concept_id:"dwes_u2_q17", unit:2, question:"¿Qué estructura de control alternativa a switch fue introducida en PHP 8.0?", options:["select","match","when","case_of"], correct:1, explanation:"'match' es una expresión que devuelve un valor, utiliza comparación estricta (===), no necesita break y lanza un UnhandledMatchError si no coincide.", noShuffle:false },
  { concept_id:"dwes_u2_q18", unit:2, question:"¿Cuál es la función para volcar información detallada de una variable incluyendo su tipo y longitud?", options:["print_r()","var_dump()","echo()","inspect()"], correct:1, explanation:"var_dump() proporciona volcado exhaustivo con tipos, tamaños y estructuras anidadas. print_r() es más legible pero no muestra tipos.", noShuffle:false },
  { concept_id:"dwes_u2_q19", unit:2, question:"¿Cómo se convierte explícitamente una variable a entero en PHP (type casting)?", options:["to_int($var)","(int)$var o (integer)$var","$var.asInt()","intval() es la única forma"], correct:1, explanation:"Tanto el casting explícito (int)$var como la función intval($var) convierten un valor a entero.", noShuffle:false },
  { concept_id:"dwes_u2_q20", unit:2, question:"¿Qué son las variables superglobales en PHP?", options:["Variables creadas por el sistema operativo, concepto diferente al que se describe en esta pregunta","Arrays asociativos predefinidos disponibles automáticamente en todos los ámbitos y funciones sin necesidad de declararlas globales","Variables que se guardan en la nube, concepto diferente al que se describe en esta pregunta","Variables constantes de solo lectura, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Superglobales como $_GET, $_POST, $_SESSION, $_SERVER están siempre accesibles globalmente en cualquier parte del código.", noShuffle:false },
  { concept_id:"dwes_u2_q21", unit:2, question:"¿Qué contiene el array superglobal $_SERVER?", options:["El contenido de la base de datos, concepto que se aplica en un contexto distinto","Información del entorno del servidor, cabeceras de la petición","La configuración de php.ini, concepto que se aplica en un contexto distinto","Archivos temporales del sistema, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"$_SERVER contiene cabeceras, rutas como REQUEST_URI, SCRIPT_FILENAME, HTTP_HOST, REMOTE_ADDR, etc.", noShuffle:false },
  { concept_id:"dwes_u2_q22", unit:2, question:"¿Cómo se declara el modo de tipos estrictos en un archivo PHP?", options:["use strict;, concepto diferente al que se describe en esta pregunta","declare(strict_types=1);","type_mode(strict);","#pragma strict, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"declare(strict_types=1); debe ser la primera sentencia del archivo PHP para exigir concordancia estricta de tipos de parámetros y retornos.", noShuffle:false },
  { concept_id:"dwes_u2_q23", unit:2, question:"¿Cuál es la salida de: echo (int)'15 gatos'; en PHP?", options:["Error de sintaxis","0","15","NULL"], correct:2, explanation:"Al castear a int una cadena que empieza por números, PHP extrae la porción numérica inicial (15). Si no empieza por dígitos, devuelve 0.", noShuffle:false },
  { concept_id:"dwes_u2_q24", unit:2, question:"¿Qué significa el tipo especial 'null' en PHP?", options:["Cero numérico, concepto diferente al que se describe en esta pregunta","Una variable sin valor asignado o explícitamente establecida con la constante NULL","Un string de longitud 0, concepto diferente al que se describe en esta pregunta","Un array sin elementos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"null representa la ausencia intencionada de valor. is_null($var) comprueba si una variable es null.", noShuffle:false },
  { concept_id:"dwes_u2_q25", unit:2, question:"¿Qué operador ternario abreviado existe en PHP?", options:["$x = $a ?: $b; (Elvis operator)","$x = $a ?? $b;, concepto diferente al que se describe en esta pregunta","$x = $a !: $b;, concepto diferente al que se describe en esta pregunta","$x = $a | $b;, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"El operador Elvis ($a ?: $b) evalúa $a; si es truthy devuelve $a, si es falsy devuelve $b.", noShuffle:false },
  { concept_id:"dwes_u2_q26", unit:2, question:"¿Cómo se escriben comentarios multilínea en PHP?", options:["# comentario","#* comentario *#","/* comentario */","<!-- comentario -->"], correct:2, explanation:"/* ... */ delimita comentarios de varias líneas. // y # son para comentarios de una sola línea.", noShuffle:false },
  { concept_id:"dwes_u2_q27", unit:2, question:"¿Qué ocurre si se omite la etiqueta de cierre '?>' en un archivo con solo código PHP?", options:["Lanza un Fatal Parse Error, concepto diferente al que se describe en esta pregunta","Es una buena práctica recomendada por PSR-12 para evitar espacios en blanco accidentales enviados al buffer","El servidor no compila el script, concepto diferente al que se describe en esta pregunta","El navegador interpreta el código como texto plano, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Omitir la etiqueta final de cierre previene el envío involuntario de saltos de línea o espacios que romperían cabeceras (headers already sent).", noShuffle:false },
  { concept_id:"dwes_u2_q28", unit:2, question:"¿Qué función detiene la ejecución del script PHP de inmediato imprimiendo un mensaje opcional?", options:["stop(), concepto diferente al que se describe en esta pregunta","die() o exit()","abort(), concepto diferente al que se describe en esta pregunta","break;, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"die() y exit() son equivalentes: finalizan el script de forma inmediata y pueden emitir un mensaje de cierre.", noShuffle:false },
  { concept_id:"dwes_u2_q29", unit:2, question:"¿Qué significa que PHP sea un lenguaje débilmente tipado?", options:["Que sus tipos se degradan con el tiempo, concepto diferente al que se describe en esta pregunta","Que no requiere declarar tipos de variables y realiza conversiones automáticas entre tipos compatibles según el contexto","Que tiene pocos tipos de datos, concepto diferente al que se describe en esta pregunta","Que no soporta orientación a objetos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"PHP realiza coerción de tipos automática (ej: sumar string y número) a menos que se active strict_types=1.", noShuffle:false },
  { concept_id:"dwes_u2_q30", unit:2, question:"¿Qué es el operador de asignación con coalescencia nula introducido en PHP 7.4?", options:["??=","?:=","?=","&&="], correct:0, explanation:"$a ??= $b; asigna el valor de $b a $a únicamente si $a es null o no está definida.", noShuffle:false },
  { concept_id:"dwes_u2_q31", unit:2, question:"¿Qué nivel de error en PHP no detiene la ejecución pero advierte de una mala práctica o deprecación?", options:["E_ERROR, concepto diferente al que se describe en esta pregunta","E_PARSE, concepto diferente al que se describe en esta pregunta","E_DEPRECATED y E_NOTICE","E_CORE_ERROR, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"E_NOTICE y E_DEPRECATED son avisos informativos que no interrumpen el flujo del script.", noShuffle:false },
  { concept_id:"dwes_u2_q32", unit:2, question:"¿Cuál es el valor booleano de la cadena '0' en PHP?", options:["true","false","null","Lanza TypeError"], correct:1, explanation:"En PHP, tanto '' (cadena vacía) como '0' (cadena con un solo cero) se evalúan como boolean false.", noShuffle:false },
  { concept_id:"dwes_u2_q33", unit:2, question:"¿Qué función de PHP devuelve el tipo de dato de una variable en formato string?", options:["typeof()","gettype()","type_of()","var_type()"], correct:1, explanation:"gettype($var) devuelve strings como 'integer', 'string', 'boolean', 'double', 'array', 'object', 'NULL'.", noShuffle:false },
  { concept_id:"dwes_u2_q34", unit:2, question:"¿Qué sintaxis permite definir strings multilínea preservando comillas y formato sin escapar en PHP?", options:["Templates, concepto diferente al que se describe en esta pregunta","Heredoc (<<<EOD) y Nowdoc (<<<'EOD')","Raw strings R\"()\", concepto diferente al que se describe en esta pregunta","Backticks ``, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Heredoc evalúa variables internas, mientras que Nowdoc las trata como texto puro sin interpolar.", noShuffle:false },
  { concept_id:"dwes_u2_q35", unit:2, question:"¿Qué función se utiliza para comprobar si un archivo o directorio existe en el servidor?", options:["file_exists()","exists()","is_file_there()","has_file()"], correct:0, explanation:"file_exists($ruta) comprueba tanto la existencia de archivos regulares como de directorios.", noShuffle:false },
  { concept_id:"dwes_u2_q36", unit:2, question:"¿Qué hace la función phpinfo()?", options:["Muestra el código fuente de PHP, concepto diferente al que se describe en esta pregunta","Genera y muestra una página HTML exhaustiva con la configuración actual de PHP, módulos cargados y variables de entorno","Descarga la última actualización de PHP, concepto diferente al que se describe en esta pregunta","Ejecuta un benchmark de velocidad, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"phpinfo() es muy útil para diagnóstico en desarrollo, pero debe restringirse en producción por revelar datos sensibles.", noShuffle:false },
  { concept_id:"dwes_u2_q37", unit:2, question:"¿Cómo se accede al número de argumentos pasados a un script PHP ejecutado desde la línea de comandos (CLI)?", options:["$argc","$_GET['args']","$_SERVER['CLI_COUNT']","$argv.length"], correct:0, explanation:"En CLI, $argc almacena el conteo de argumentos y $argv es el array con los valores pasados.", noShuffle:false },
  { concept_id:"dwes_u2_q38", unit:2, question:"¿Qué operador se utiliza para ejecutar comandos del sistema operativo en el servidor?", options:["Comillas dobles \"\", concepto diferente al que se describe en esta pregunta","Comillas invertidas `` (backticks) o shell_exec()","Corchetes []","Signos de exclamación !!"], correct:1, explanation:"Los backticks `ls -la` ejecutan el comando en la shell del sistema y devuelven la salida como string.", noShuffle:false },
  { concept_id:"dwes_u2_q39", unit:2, question:"¿Cuál es la función para redirigir al navegador a otra página enviando la cabecera Location en PHP?", options:["redirect('url')","header('Location: url');","window.location = 'url';","http_redirect('url');"], correct:1, explanation:"header('Location: url'); envía el código HTTP 302 y la URL destino. Se debe añadir exit; inmediatamente después.", noShuffle:false },
  { concept_id:"dwes_u2_q40", unit:2, question:"¿Qué error común se produce si se llama a header() después de haber hecho un echo en PHP?", options:["Headers already sent warning","Fatal database error","Memory limit exceeded","Parse error, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"'Cannot modify header information - headers already sent' ocurre porque las cabeceras HTTP deben enviarse antes de cualquier byte del cuerpo.", noShuffle:false },
  { concept_id:"dwes_u2_q41", unit:2, question:"¿Qué función activa el almacenamiento en buffer de la salida para evitar el error de cabeceras?", options:["buffer_start()","ob_start()","output_cache()","stream_open()"], correct:1, explanation:"ob_start() (Output Buffering) retiene la salida en memoria interna hasta que se descargue con ob_end_flush().", noShuffle:false },
  { concept_id:"dwes_u2_q42", unit:2, question:"¿Qué constante mágica en PHP devuelve el número de línea actual del script?", options:["__FILE__","__LINE__","__DIR__","__METHOD__"], correct:1, explanation:"__LINE__ devuelve el número de línea. __FILE__ la ruta completa del archivo y __DIR__ el directorio actual.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 3 — Funciones y Arrays en PHP
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwes_u3_q1", unit:3, question:"¿Cómo se define una función básica en PHP?", options:["def suma($a, $b) {}","function suma($a, $b) {}","func suma($a, $b) {}","fn suma($a, $b) {}"], correct:1, explanation:"La palabra reservada estándar para funciones en PHP es 'function'.", noShuffle:false },
  { concept_id:"dwes_u3_q2", unit:3, question:"¿Cómo se pasa un parámetro por referencia en una función PHP?", options:["function duplicar(&$numero) {}","function duplicar(ref $numero) {}","function duplicar(*$numero) {}","function duplicar($numero) byref {}"], correct:0, explanation:"El ampersand (&) antepuesto al parámetro indica paso por referencia, modificando la variable original externa.", noShuffle:false },
  { concept_id:"dwes_u3_q3", unit:3, question:"¿Qué diferencia a los arrays en PHP de los de lenguajes como C o Java?", options:["En PHP solo admiten números, concepto diferente al que se describe en esta pregunta","En PHP los arrays son en realidad mapas ordenados asociativos: admiten índices enteros o claves string arbitrarias y longitud dinámica","En PHP tienen tamaño fijo inmutable, concepto diferente al que se describe en esta pregunta","No se pueden anidar, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los arrays de PHP implementan internamente una tabla hash ordenada y dinámica que sirve como lista, cola, pila y diccionario.", noShuffle:false },
  { concept_id:"dwes_u3_q4", unit:3, question:"¿Cómo se añade un elemento al final de un array indexado en PHP de forma abreviada?", options:["$array.push($item);","$array[] = $item;","array_append($array, $item);","$array += $item;"], correct:1, explanation:"$array[] = $valor; calcula el siguiente índice entero disponible y asigna el valor eficientemente.", noShuffle:false },
  { concept_id:"dwes_u3_q5", unit:3, question:"¿Qué función devuelve el número total de elementos de un array?", options:["sizeof() o count()","length($array)","$array.length","array_size()"], correct:0, explanation:"count($array) (y su alias sizeof) devuelve la cantidad de elementos. Admite COUNT_RECURSIVE para arrays multidimensionales.", noShuffle:false },
  { concept_id:"dwes_u3_q6", unit:3, question:"¿Cómo se itera sobre claves y valores de un array asociativo en PHP?", options:["for ($array as $k => $v) {}","foreach ($array as $clave => $valor) {}","loop ($array : $clave => $valor) {}","while ($array.next()) {}"], correct:1, explanation:"foreach ($array as $clave => $valor) es la estructura óptima e idiomática para recorrer arrays en PHP.", noShuffle:false },
  { concept_id:"dwes_u3_q7", unit:3, question:"¿Qué función comprueba si una clave o índice específico existe dentro de un array?", options:["in_array(), concepto diferente al que se describe en esta pregunta","array_key_exists() o isset()","has_key(), concepto diferente al que se describe en esta pregunta","key_exists_in(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"array_key_exists($clave, $array) comprueba la clave incluso si el valor es null. isset() es más rápida pero da false si el valor es null.", noShuffle:false },
  { concept_id:"dwes_u3_q8", unit:3, question:"¿Qué función busca si un determinado valor existe dentro de un array?", options:["in_array($valor, $array)","array_search() exclusivamente","array_contains()","has_value()"], correct:0, explanation:"in_array($busqueda, $array, $estricto) devuelve true si el elemento está presente. Con $estricto = true usa comparación estricta (===).", noShuffle:false },
  { concept_id:"dwes_u3_q9", unit:3, question:"¿Qué función busca un valor en un array y devuelve su clave correspondiente si lo encuentra?", options:["array_key()","array_search()","array_find()","in_array_key()"], correct:1, explanation:"array_search() localiza el valor y retorna la clave o índice asociado, o false si no lo encuentra.", noShuffle:false },
  { concept_id:"dwes_u3_q10", unit:3, question:"¿Cómo se define una función con número variable de argumentos (variadic) en PHP?", options:["function registrar(...$items) {}","function registrar(*$items) {}","function registrar(params $items) {}","function registrar(array $items) {}"], correct:0, explanation:"El operador elipsis (...) agrupa los argumentos restantes en un array dentro de la función.", noShuffle:false },
  { concept_id:"dwes_u3_q11", unit:3, question:"¿Cómo se definen argumentos con nombre (Named Arguments) al llamar a una función en PHP 8+?", options:["miFuncion(@nombre='Ana', @edad=20);","miFuncion(nombre: 'Ana', edad: 20);","miFuncion({nombre: 'Ana', edad: 20});","miFuncion(name => 'Ana');"], correct:1, explanation:"Desde PHP 8, los argumentos con nombre permiten pasar valores indicando 'parametro: valor', independientemente del orden.", noShuffle:false },
  { concept_id:"dwes_u3_q12", unit:3, question:"¿Qué sintaxis tienen las funciones flecha (arrow functions) introducidas en PHP 7.4?", options:["$doble = ($x) => $x * 2;","$doble = fn($x) => $x * 2;","$doble = function($x) => $x * 2;","$doble = lambda $x: $x * 2;"], correct:1, explanation:"fn(argumentos) => expresion captura automáticamente variables del ámbito exterior por valor.", noShuffle:false },
  { concept_id:"dwes_u3_q13", unit:3, question:"¿Cómo importa una función anónima clásica (closure) variables de su ámbito exterior en PHP?", options:["Con la palabra clave global","Con la cláusula 'use': function() use ($varExterior) {}","Las importa automáticamente siempre","Con this.varExterior"], correct:1, explanation:"A diferencia de JavaScript, las funciones anónimas estándar en PHP requieren indicar 'use ($variable)' para acceder al scope externo.", noShuffle:false },
  { concept_id:"dwes_u3_q14", unit:3, question:"¿Qué función transforma un string en array dividiéndolo por un delimitador?", options:["split(), concepto diferente al que se describe en esta pregunta","explode($delimitador, $cadena)","str_split(), concepto diferente al que se describe en esta pregunta","tokenize(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"explode(',', 'a,b,c') produce ['a','b','c']. str_split divide en trozos de caracteres.", noShuffle:false },
  { concept_id:"dwes_u3_q15", unit:3, question:"¿Qué función une los elementos de un array en un único string usando un separador?", options:["join() o implode($separador, $array)","concat_array(), concepto diferente al que se describe en esta pregunta","array_join(), concepto diferente al que se describe en esta pregunta","merge_string(), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"implode('-', ['a','b','c']) genera 'a-b-c'. 'join' es un alias de implode.", noShuffle:false },
  { concept_id:"dwes_u3_q16", unit:3, question:"¿Cuál es la función para fusionar dos o más arrays en uno nuevo?", options:["array_combine()","array_merge($arr1, $arr2)","array_push_array()","$arr1 + $arr2 exclusivamente"], correct:1, explanation:"array_merge() combina elementos. En claves string, los valores posteriores sobreescriben a los anteriores; en índices numéricos, los reindexa.", noShuffle:false },
  { concept_id:"dwes_u3_q17", unit:3, question:"¿Qué diferencia hay entre sort() y asort() en PHP?", options:["sort() ordena arrays multidimensionales y asort() planos","sort() ordena y reindexa numéricamente perdiendo las claves","asort() ordena en orden descendente, concepto diferente al que se describe en esta pregunta","No hay diferencia, aunque algunos enfoques establecen matices al respecto"], correct:1, explanation:"asort() preserva las claves (ideal para asociativos). sort() descarta claves y asigna 0, 1, 2... ksort() ordena por las claves.", noShuffle:false },
  { concept_id:"dwes_u3_q18", unit:3, question:"¿Qué función se utiliza para ordenar un array usando una función de comparación definida por el desarrollador?", options:["custom_sort()","usort() (para reindexar) y uasort() (preservando claves)","sort_by()","array_sort_fn()"], correct:1, explanation:"usort($array, function($a, $b) { return $a <=> $b; }); permite lógica de ordenación arbitraria.", noShuffle:false },
  { concept_id:"dwes_u3_q19", unit:3, question:"¿Qué función aplica un callback a cada elemento de uno o más arrays y devuelve un nuevo array?", options:["array_each(), concepto diferente al que se describe en esta pregunta","array_map($callback, $array)","array_walk(), concepto diferente al que se describe en esta pregunta","array_filter(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"array_map() genera un nuevo array aplicando la función pasada a cada valor. array_walk() itera in-place.", noShuffle:false },
  { concept_id:"dwes_u3_q20", unit:3, question:"¿Qué función filtra elementos de un array según una función predicado?", options:["array_select(), concepto diferente al que se describe en esta pregunta","array_filter($array, $callback)","array_find_all(), concepto diferente al que se describe en esta pregunta","filter(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"array_filter() conserva solo los elementos para los que la función callback devuelve true. Si se omite callback, elimina falsy.", noShuffle:false },
  { concept_id:"dwes_u3_q21", unit:3, question:"¿Qué función reduce iterativamente un array a un único valor acumulado?", options:["array_sum(), concepto diferente al que se describe en esta pregunta","array_reduce($array, $callback, $inicial)","array_collapse(), concepto diferente al que se describe en esta pregunta","array_aggregate(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"array_reduce() procesa el array secuencialmente aplicando un acumulador, análogo a Array.prototype.reduce en JS.", noShuffle:false },
  { concept_id:"dwes_u3_q22", unit:3, question:"¿Cómo se eliminan elementos duplicados de un array en PHP?", options:["array_unique($array)","array_distinct()","array_dedup()","unique($array)"], correct:0, explanation:"array_unique() compara valores como string y devuelve el array sin duplicados, conservando las primeras claves encontradas.", noShuffle:false },
  { concept_id:"dwes_u3_q23", unit:3, question:"¿Qué hace la función array_pop()?", options:["Extrae y devuelve el primer elemento del array, concepto diferente al que se describe en esta pregunta","Extrae y devuelve el último elemento del array, reduciendo su longitud","Añade un elemento al principio, concepto diferente al que se describe en esta pregunta","Invierte el orden del array, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"array_pop() retira el último elemento. Para el primero se usa array_shift().", noShuffle:false },
  { concept_id:"dwes_u3_q24", unit:3, question:"¿Qué hace la función array_shift()?", options:["Extrae y devuelve el primer elemento del array, reindexando las claves numéricas","Añade un elemento al principio, concepto diferente al que se describe en esta pregunta","Extrae el último elemento, concepto diferente al que se describe en esta pregunta","Desplaza los índices cíclicamente, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"array_shift() retira el primer elemento. Su inverso para insertar al inicio es array_unshift().", noShuffle:false },
  { concept_id:"dwes_u3_q25", unit:3, question:"¿Qué función extrae únicamente las claves de un array asociativo?", options:["array_values()","array_keys($array)","keys($array)","get_keys()"], correct:1, explanation:"array_keys() devuelve un array indexado con todos los nombres de claves. array_values() extrae los valores.", noShuffle:false },
  { concept_id:"dwes_u3_q26", unit:3, question:"¿Qué función crea un array asociativo usando un array para las claves y otro para los valores?", options:["array_merge(), concepto diferente al que se describe en esta pregunta","array_combine($claves, $valores)","array_pair(), concepto diferente al que se describe en esta pregunta","array_map_keys(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"array_combine(['id','nombre'], [1,'Ana']) devuelve ['id' => 1, 'nombre' => 'Ana']. Ambos arrays deben tener la misma longitud.", noShuffle:false },
  { concept_id:"dwes_u3_q27", unit:3, question:"¿Cómo se define el tipo de retorno en una función PHP moderna?", options:["function calcular(): float {}","float function calcular() {}","function calcular() returns float {}","function:float calcular() {}"], correct:0, explanation:"Los dos puntos tras la lista de parámetros indican el tipo de retorno: function calcular(int $a): float { return $a * 1.5; }", noShuffle:false },
  { concept_id:"dwes_u3_q28", unit:3, question:"¿Qué tipo de retorno introducido en PHP 7.1 indica que la función no retorna ningún valor?", options:["null","void","never","empty"], correct:1, explanation:"'void' indica ausencia de retorno. 'never' (PHP 8.1) indica que la función siempre lanza una excepción o termina con exit/die.", noShuffle:false },
  { concept_id:"dwes_u3_q29", unit:3, question:"¿Cómo se especifica que un parámetro o retorno puede ser de un tipo específico O nulo (nullable type)?", options:["int|null o ?int","nullable(int)","int?","$int || null"], correct:0, explanation:"Prefijar con interrogación ?int o usar unión int|null permite aceptar tanto enteros como el valor null.", noShuffle:false },
  { concept_id:"dwes_u3_q30", unit:3, question:"¿Qué son los 'Union Types' disponibles desde PHP 8.0?", options:["Unir dos tipos en un string","Poder declarar múltiples tipos alternativos para un parámetro o retorno mediante barra vertical: int|float|string","Tipos para bases de datos relacionales","Clases de tipo compuesto"], correct:1, explanation:"Permite declarar firmas flexibles: function procesar(int|string $dato): bool|array { ... }", noShuffle:false },
  { concept_id:"dwes_u3_q31", unit:3, question:"¿Qué función invierte el orden de los elementos de un array?", options:["array_reverse($array)","reverse($array)","array_invert(), concepto diferente al que se describe en esta pregunta","sort_reverse(), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"array_reverse() devuelve un array nuevo con los elementos en orden inverso. Admite un segundo parámetro booleano para preservar claves numéricas.", noShuffle:false },
  { concept_id:"dwes_u3_q32", unit:3, question:"¿Qué operador permite desempaquetar (spread) un array en PHP 7.4+?", options:["...$array","*$array","&$array","@$array"], correct:0, explanation:"$final = [...$arr1, ...$arr2]; expande los elementos en el punto de inserción.", noShuffle:false },
  { concept_id:"dwes_u3_q33", unit:3, question:"¿Qué función calcula la suma de todos los valores numéricos de un array?", options:["count(), concepto diferente al que se describe en esta pregunta","array_sum($array)","sum($array), concepto diferente al que se describe en esta pregunta","array_total()"], correct:1, explanation:"array_sum([2, 4, 6]) retorna 12. Para el producto existe array_product().", noShuffle:false },
  { concept_id:"dwes_u3_q34", unit:3, question:"¿Qué devuelve array_diff($array1, $array2)?", options:["Los elementos comunes, concepto diferente al que se describe en esta pregunta","Los elementos de $array1 que NO están presentes en $array2","Las diferencias de longitud, concepto que se aplica en un contexto distinto","Un booleano, concepto que no se corresponde con la definicion correcta"], correct:1, explanation:"array_diff() calcula la diferencia de conjuntos basándose en los valores. Para intersección se usa array_intersect().", noShuffle:false },
  { concept_id:"dwes_u3_q35", unit:3, question:"¿Cómo se extrae una porción de un array sin modificar el original en PHP?", options:["array_splice(), concepto diferente al que se describe en esta pregunta","array_slice($array, $offset, $length)","array_cut(), concepto diferente al que se describe en esta pregunta","substr_array(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"array_slice() extrae una porción sin alterar el array original. array_splice() en cambio sí lo modifica eliminando o sustituyendo.", noShuffle:false },
  { concept_id:"dwes_u3_q36", unit:3, question:"¿Qué ocurre si una función intenta modificar una variable global sin declararla previamente con 'global'?", options:["Modifica la variable global directamente, concepto diferente al que se describe en esta pregunta","Crea una nueva variable local con el mismo nombre y la variable global no se altera","Lanza un Fatal Error, concepto diferente al que se describe en esta pregunta","Se detiene el script, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"En PHP el ámbito local está completamente aislado del global a menos que se use la instrucción 'global $var;' o $GLOBALS['var'].", noShuffle:false },
  { concept_id:"dwes_u3_q37", unit:3, question:"¿Qué es una variable estática (static) dentro de una función PHP?", options:["Una constante inmutable, concepto diferente al que se describe en esta pregunta","Una variable local que conserva su valor entre sucesivas llamadas a la misma función","Una variable compartida entre servidores, concepto diferente al que se describe en esta pregunta","Una variable de sesión, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"static $contador = 0; no se reinicializa en llamadas posteriores, manteniendo el estado interno de la función.", noShuffle:false },
  { concept_id:"dwes_u3_q38", unit:3, question:"¿Qué función permite desestructurar los elementos de un array en variables individuales?", options:["unpack()","list($a, $b) = $array; o [$a, $b] = $array;","extract_vars()","spread()"], correct:1, explanation:"[$primero, $segundo] = $miArray; asigna los elementos indexados directamente a variables individuales.", noShuffle:false },
  { concept_id:"dwes_u3_q39", unit:3, question:"¿Qué función importa las claves de un array asociativo directamente como variables locales?", options:["import_keys()","extract($array)","vars_from_array()","compact()"], correct:1, explanation:"extract() crea variables locales con los nombres de las claves del array. Debe usarse con precaución frente a datos de usuario.", noShuffle:false },
  { concept_id:"dwes_u3_q40", unit:3, question:"¿Qué función realiza la operación inversa a extract(), creando un array a partir de variables y sus nombres?", options:["implode(), concepto diferente al que se describe en esta pregunta","compact('var1', 'var2')","collect(), concepto diferente al que se describe en esta pregunta","wrap_vars(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"compact('nombre', 'edad') busca las variables locales $nombre y $edad y construye ['nombre' => ..., 'edad' => ...].", noShuffle:false },
  { concept_id:"dwes_u3_q41", unit:3, question:"¿Qué hace array_column($arrayMultidimensional, 'columna')?", options:["Ordena por esa columna, concepto diferente al que se describe en esta pregunta","Extrae todos los valores de una columna concreta de un array de registros o matriz","Borra la columna, concepto diferente al que se describe en esta pregunta","Cuenta los valores, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"array_column($usuarios, 'email') devuelve una lista unidimensional solo con los correos, muy útil al procesar resultados de BD.", noShuffle:false },
  { concept_id:"dwes_u3_q42", unit:3, question:"¿Qué función permite ejecutar una llamada a función usando su nombre dinámico en string?", options:["call_user_func($nombreFuncion, ...$params) o $nombreFuncion(...$params)","invoke(), concepto diferente al que se describe en esta pregunta","execute_fn(), concepto diferente al que se describe en esta pregunta","eval_function(), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"PHP permite invocar funciones variables $fn() directamente o mediante call_user_func() / call_user_func_array().", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 4 — Acceso a Bases de Datos con PDO
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwes_u4_q1", unit:4, question:"¿Qué significan las siglas PDO en PHP?", options:["PHP Database Object","PHP Data Objects","PostgreSQL Data Operations","Personal Data Organizer"], correct:1, explanation:"PDO es una capa de abstracción de acceso a bases de datos ligera y consistente para PHP.", noShuffle:false },
  { concept_id:"dwes_u4_q2", unit:4, question:"¿Cuál es la principal ventaja de usar PDO sobre la extensión MySQLi?", options:["PDO solo soporta MySQL, concepto diferente al que se describe en esta pregunta","PDO ofrece una interfaz homogénea que soporta hasta 12 controladores de bases de datos diferentes (MySQL, PostgreSQL, SQLite, Oracle...)","PDO no requiere usuario ni contraseña, concepto diferente al que se describe en esta pregunta","PDO no lanza excepciones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Con PDO el código para consultar o ejecutar sentencias es prácticamente idéntico si cambias de MySQL a PostgreSQL o SQLite.", noShuffle:false },
  { concept_id:"dwes_u4_q3", unit:4, question:"¿Qué es el DSN (Data Source Name) en una conexión PDO?", options:["El nombre de usuario administrador, concepto que se aplica en un contexto distinto","La cadena de conexión que especifica el driver, host, nombre de la base de datos, puerto y charset","La contraseña encriptada, concepto diferente al que se describe en esta pregunta","La versión de MySQL, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Ejemplo de DSN: 'mysql:host=localhost;dbname=tienda;charset=utf8mb4'. Contiene la información de localización.", noShuffle:false },
  { concept_id:"dwes_u4_q4", unit:4, question:"¿Cómo se instancia una nueva conexión PDO?", options:["$db = PDO::connect($dsn, $user, $pass);","$db = new PDO($dsn, $user, $pass, $opciones);","$db = pdo_open($dsn);","$db = Database::create($dsn);"], correct:1, explanation:"Se instancia con 'new PDO($dsn, $usuario, $password, $opciones);'. Lanza una PDOException si falla la conexión.", noShuffle:false },
  { concept_id:"dwes_u4_q5", unit:4, question:"¿Por qué se deben usar sentencias preparadas (Prepared Statements) al interactuar con bases de datos?", options:["Para compilar el código en C, concepto diferente al que se describe en esta pregunta","Para prevenir ataques de inyección SQL (SQL Injection) separando la estructura de la consulta de los datos","Para evitar abrir transacciones, concepto diferente al que se describe en esta pregunta","Porque las consultas normales no devuelven datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las sentencias preparadas envían la plantilla SQL y los parámetros por separado al motor de BD, haciendo imposible alterar la lógica SQL.", noShuffle:false },
  { concept_id:"dwes_u4_q6", unit:4, question:"¿Cuáles son las dos formas de definir marcadores de posición en una sentencia preparada con PDO?", options:["Signos de interrogación posicionales (?) y marcadores con nombre (:nombre)","Porcentajes (%) y arrobas (@)","Dólares ($1) exclusivamente","Llaves {campo}"], correct:0, explanation:"PDO admite tanto 'WHERE id = ?' (posicional) como 'WHERE id = :id' (con nombre, más legible).", noShuffle:false },
  { concept_id:"dwes_u4_q7", unit:4, question:"¿Cuál es la diferencia entre bindValue() y bindParam() en PDOStatement?", options:["Son idénticos, concepto diferente al que se describe en esta pregunta","bindValue() asocia un valor inmediato; bindParam() asocia el parámetro por referencia a una variable que se evalúa al ejecutar execute()","bindParam() es solo para enteros, concepto diferente al que se describe en esta pregunta","bindValue() solo funciona con marcadores ?, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Con bindParam() la variable se pasa por referencia y su valor se lee en el momento de invocar execute(), útil en bucles.", noShuffle:false },
  { concept_id:"dwes_u4_q8", unit:4, question:"¿Cómo se ejecuta una sentencia preparada en PDO pasando un array asociativo de parámetros?", options:["$stmt->run([':id' => 5]);","$stmt->execute([':id' => 5]);","$stmt->query([':id' => 5]);","$stmt->send(['id' => 5]);"], correct:1, explanation:"$stmt->execute([':id' => $id]) es la forma más directa y limpia de enlazar y ejecutar parámetros.", noShuffle:false },
  { concept_id:"dwes_u4_q9", unit:4, question:"¿Qué modo de fetch devuelve cada fila como un array asociativo con los nombres de columna?", options:["PDO::FETCH_NUM","PDO::FETCH_ASSOC","PDO::FETCH_BOTH","PDO::FETCH_OBJ"], correct:1, explanation:"PDO::FETCH_ASSOC indexa el resultado por los nombres de las columnas: $fila['email']. PDO::FETCH_OBJ lo devuelve como objeto anónimo.", noShuffle:false },
  { concept_id:"dwes_u4_q10", unit:4, question:"¿Qué método de PDOStatement obtiene todas las filas resultantes de una sola vez como un array?", options:["$stmt->fetch()","$stmt->fetchAll()","$stmt->getAll()","$stmt->to_array()"], correct:1, explanation:"fetchAll(PDO::FETCH_ASSOC) descarga todo el conjunto de resultados a un array de PHP en memoria.", noShuffle:false },
  { concept_id:"dwes_u4_q11", unit:4, question:"¿Cómo se configura PDO para que lance excepciones ante cualquier error SQL?", options:["$pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION)","$pdo->setExceptions(true);, concepto diferente al que se describe en esta pregunta","$pdo->error_mode = 'throw';, concepto diferente al que se describe en esta pregunta","En php.ini exclusivamente, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"ERRMODE_EXCEPTION transforma fallos de consulta en excepciones de tipo PDOException capturables en bloques try/catch.", noShuffle:false },
  { concept_id:"dwes_u4_q12", unit:4, question:"¿Qué método de PDO obtiene el último ID autoincremental insertado en la base de datos?", options:["$pdo->lastInsertId()","$stmt->insertedId()","$pdo->getLastId()","mysql_insert_id()"], correct:0, explanation:"$pdo->lastInsertId() devuelve el identificador generado por la última operación INSERT.", noShuffle:false },
  { concept_id:"dwes_u4_q13", unit:4, question:"¿Cómo se inicia una transacción en PDO?", options:["$pdo->startTransaction();","$pdo->beginTransaction();","$pdo->begin();","$pdo->query('START TRANSACTION'); únicamente"], correct:1, explanation:"$pdo->beginTransaction() apaga el modo autocommit e inicia formalmente una transacción ACID.", noShuffle:false },
  { concept_id:"dwes_u4_q14", unit:4, question:"¿Qué método confirma los cambios de una transacción haciéndolos permanentes en la base de datos?", options:["$pdo->commit()","$pdo->save()","$pdo->apply()","$pdo->endTransaction()"], correct:0, explanation:"$pdo->commit() consolida definitivamente todas las operaciones ejecutadas desde beginTransaction().", noShuffle:false },
  { concept_id:"dwes_u4_q15", unit:4, question:"¿Qué método cancela una transacción y revierte todos los cambios en caso de error?", options:["$pdo->rollback()","$pdo->cancel()","$pdo->undo()","$pdo->revert()"], correct:0, explanation:"$pdo->rollBack() deshace todas las operaciones de la transacción, garantizando la consistencia de datos.", noShuffle:false },
  { concept_id:"dwes_u4_q16", unit:4, question:"¿Cuál es la diferencia entre el método query() y el método exec() en el objeto PDO?", options:["No hay diferencia, aunque algunos enfoques establecen matices al respecto","query() se usa para consultas que devuelven filas (SELECT) retornando un PDOStatement; exec() se usa para INSERT/UPDATE/DELETE y devuelve el número de filas afectadas","exec() es para sentencias preparadas, concepto diferente al que se describe en esta pregunta","query() no admite SQL, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"exec() devuelve un entero con las filas afectadas o false si falla, ideal para DDL o sentencias simples sin retorno de filas.", noShuffle:false },
  { concept_id:"dwes_u4_q17", unit:4, question:"¿Qué propiedad de PDOStatement indica cuántas filas fueron afectadas por un UPDATE, DELETE o INSERT?", options:["$stmt->count()","$stmt->rowCount()","$stmt->affectedRows()","$stmt->length"], correct:1, explanation:"$stmt->rowCount() devuelve el total de registros modificados o eliminados por la última sentencia.", noShuffle:false },
  { concept_id:"dwes_u4_q18", unit:4, question:"¿Qué modo de fetch mapea directamente cada fila resultante a una instancia de una clase específica?", options:["PDO::FETCH_ASSOC","PDO::FETCH_CLASS","PDO::FETCH_INTO","PDO::FETCH_MODEL"], correct:1, explanation:"PDO::FETCH_CLASS instancia la clase indicada y asigna los valores de las columnas a las propiedades con el mismo nombre.", noShuffle:false },
  { concept_id:"dwes_u4_q19", unit:4, question:"¿Por qué se debe desactivar la emulación de sentencias preparadas en PDO MySQL con ATTR_EMULATE_PREPARES a false?", options:["Porque acelera la red, concepto diferente al que se describe en esta pregunta","Para que sea el propio motor de MySQL quien prepare y compile la consulta nativamente, garantizando tipos reales y mayor seguridad","Porque la emulación no soporta strings, concepto diferente al que se describe en esta pregunta","Para permitir transacciones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"$pdo->setAttribute(PDO::ATTR_EMULATE_PREPARES, false) asegura el uso de sentencias preparadas reales en el servidor MySQL.", noShuffle:false },
  { concept_id:"dwes_u4_q20", unit:4, question:"¿Qué ocurre si ocurre una excepción dentro de un bloque de transacción y no se llama a commit() ni a rollBack()?", options:["Se confirma automáticamente, concepto diferente al que se describe en esta pregunta","Al cerrarse la conexión o finalizar el script, PDO revierte la transacción automáticamente por seguridad","La base de datos se corrompe, concepto que se aplica en un contexto distinto","Se bloquea la tabla indefinidamente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si la conexión finaliza con una transacción abierta, la base de datos efectúa un rollback implícito de seguridad.", noShuffle:false },
  { concept_id:"dwes_u4_q21", unit:4, question:"¿Qué tipo de charset se recomienda especificar en el DSN de MySQL para soporte completo de caracteres y emojis?", options:["latin1","utf8","utf8mb4","ascii"], correct:2, explanation:"utf8mb4 implementa el estándar UTF-8 de 4 bytes completo, necesario para caracteres especiales y emojis sin truncamiento.", noShuffle:false },
  { concept_id:"dwes_u4_q22", unit:4, question:"¿Cómo se cierra explícitamente una conexión PDO en PHP?", options:["$pdo->close();","$pdo = null;","$pdo->disconnect();","unset_pdo($pdo);"], correct:1, explanation:"Asignar $pdo = null; elimina la última referencia al objeto, provocando que PHP cierre el socket con la base de datos.", noShuffle:false },
  { concept_id:"dwes_u4_q23", unit:4, question:"¿Qué método de PDOStatement libera el cursor permitiendo volver a ejecutar la sentencia con nuevos datos?", options:["$stmt->close()","$stmt->closeCursor()","$stmt->reset()","$stmt->free(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"$stmt->closeCursor() libera la conexión al servidor de BD para poder emitir otras consultas si no se han leído todas las filas.", noShuffle:false },
  { concept_id:"dwes_u4_q24", unit:4, question:"¿Qué tipo constante de PDO representa un valor entero al usar bindParam o bindValue?", options:["PDO::PARAM_STR","PDO::PARAM_INT","PDO::PARAM_NUM","PDO::PARAM_INTEGER"], correct:1, explanation:"PDO::PARAM_INT especifica el tipo explícito para validación y tratamiento como entero en el motor SQL.", noShuffle:false },
  { concept_id:"dwes_u4_q25", unit:4, question:"¿Qué tipo constante de PDO se usa para vincular datos binarios grandes (BLOB o imágenes)?", options:["PDO::PARAM_BIN","PDO::PARAM_LOB","PDO::PARAM_BYTE","PDO::PARAM_BLOB"], correct:1, explanation:"PDO::PARAM_LOB (Large Object) permite trabajar con streams de datos binarios sin agotar la memoria del script.", noShuffle:false },
  { concept_id:"dwes_u4_q26", unit:4, question:"¿Cuál es el peligro de concatenar variables directamente en una cadena SQL enviada a query()?", options:["Que la consulta va más lenta, concepto diferente al que se describe en esta pregunta","Inyección SQL: un atacante puede alterar la sintaxis y vaciar","Que la consulta da error de codificación, concepto diferente al que se describe en esta pregunta","Que no se pueden usar índices, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La concatenación directa es la causa primordial de las vulnerabilidades de SQL Injection más críticas de la web.", noShuffle:false },
  { concept_id:"dwes_u4_q27", unit:4, question:"¿Qué atributo de PDO permite reutilizar conexiones persistentes entre peticiones para reducir sobrecarga?", options:["PDO::ATTR_PERSISTENT => true","PDO::KEEP_ALIVE => true","PDO::ATTR_REUSE => true","PDO::POOL => true"], correct:0, explanation:"Las conexiones persistentes no se destruyen al finalizar el script, manteniéndose en caché para peticiones subsiguientes.", noShuffle:false },
  { concept_id:"dwes_u4_q28", unit:4, question:"¿Qué función cumple la constante PDO::FETCH_COLUMN?", options:["Devuelve todas las columnas, concepto diferente al que se describe en esta pregunta","Devuelve un array con solo los valores de una única columna de las filas encontradas","Ordena por columna, concepto diferente al que se describe en esta pregunta","Busca nombres de columna, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"fetchAll(PDO::FETCH_COLUMN, 0) extrae una lista plana con el valor de la columna especificada de cada fila.", noShuffle:false },
  { concept_id:"dwes_u4_q29", unit:4, question:"¿Cómo se captura específicamente un error de base de datos en PDO?", options:["catch (DatabaseException $e)","catch (PDOException $e)","catch (SQLException $e)","catch (Error $e)"], correct:1, explanation:"PDOException es la clase de excepción lanzada ante errores de conexión o fallos de ejecución SQL en PDO.", noShuffle:false },
  { concept_id:"dwes_u4_q30", unit:4, question:"¿Qué información sensible se debe evitar exponer al usuario al capturar una PDOException en producción?", options:["El color del botón, concepto diferente al que se describe en esta pregunta","El mensaje interno de error ($e->getMessage()) que puede revelar tablas","El número de filas, concepto que se aplica en un contexto distinto","La hora actual, que puede confundirse con este termino en contabilidad general"], correct:1, explanation:"Mostrar $e->getMessage() en producción revela detalles internos de la base de datos; debe registrarse en log interno y mostrar un mensaje genérico.", noShuffle:false },
  { concept_id:"dwes_u4_q31", unit:4, question:"¿Qué método de PDOStatement obtiene la siguiente fila individual de un cursor de resultados?", options:["$stmt->fetch()","$stmt->next()","$stmt->step()","$stmt->readLine()"], correct:0, explanation:"$stmt->fetch() devuelve una fila cada vez que se llama, retornando false cuando no quedan más registros por leer.", noShuffle:false },
  { concept_id:"dwes_u4_q32", unit:4, question:"¿Cómo se comprueba si la base de datos se encuentra actualmente en una transacción activa?", options:["$pdo->inTransaction()","$pdo->isTransactionActive()","$pdo->hasTransaction()","$pdo->transaction_status"], correct:0, explanation:"$pdo->inTransaction() devuelve true si se ejecutó beginTransaction() y aún no ha finalizado con commit o rollback.", noShuffle:false },
  { concept_id:"dwes_u4_q33", unit:4, question:"¿Qué atributo de PDO configura el modo de obtención de datos predeterminado para todas las consultas?", options:["PDO::ATTR_DEFAULT_FETCH_MODE","PDO::ATTR_FETCH_STYLE","PDO::DEFAULT_MODE, concepto diferente al que se describe en esta pregunta","PDO::ATTR_ROW_TYPE, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"$pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC); evita tener que especificar el modo en cada fetch().", noShuffle:false },
  { concept_id:"dwes_u4_q34", unit:4, question:"¿Qué función de PDO escapa manualmente una cadena si no se usan sentencias preparadas?", options:["$pdo->quote($string)","addslashes()","mysql_real_escape_string()","$pdo->escape()"], correct:0, explanation:"$pdo->quote() añade comillas y escapa caracteres especiales, aunque el uso de sentencias preparadas es siempre la práctica estándar.", noShuffle:false },
  { concept_id:"dwes_u4_q35", unit:4, question:"¿Qué ocurre al intentar vincular un array directamente a un marcador IN (:ids) en una sentencia preparada de PDO?", options:["Funciona automáticamente, concepto diferente al que se describe en esta pregunta","Falla: un marcador solo puede sustituir a un único valor escalar","Se convierte a JSON, concepto diferente al que se describe en esta pregunta","Lanza un error de sintaxis en PHP, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"No se puede poner 'IN (:ids)'. Se debe generar una lista de marcadores: IN (?, ?, ?) y pasar el array al execute().", noShuffle:false },
  { concept_id:"dwes_u4_q36", unit:4, question:"¿Qué diferencia hay entre PDO::FETCH_ASSOC y PDO::FETCH_NUM?", options:["FETCH_ASSOC indexa por nombres de columna (strings); FETCH_NUM indexa por posición numérica empezando en 0","FETCH_NUM convierte todos los valores a enteros, concepto diferente al que se describe en esta pregunta","FETCH_ASSOC solo lee la primera columna, concepto diferente al que se describe en esta pregunta","Son idénticos, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"FETCH_NUM devuelve [0 => 'Juan', 1 => 'juan@mail.com'], mientras que FETCH_ASSOC devuelve ['nombre' => 'Juan', 'email' => 'juan@mail.com'].", noShuffle:false },
  { concept_id:"dwes_u4_q37", unit:4, question:"¿Qué hace PDO::FETCH_KEY_PAIR?", options:["Agrupa las filas en pares aleatorios, concepto diferente al que se describe en esta pregunta","Devuelve un array asociativo donde la primera columna seleccionada actúa como clave y la segunda como valor","Compara dos claves primarias, concepto diferente al que se describe en esta pregunta","Duplica cada fila, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"SELECT id, nombre FROM usuarios con FETCH_KEY_PAIR devuelve un mapa plano [1 => 'Ana', 2 => 'Carlos'].", noShuffle:false },
  { concept_id:"dwes_u4_q38", unit:4, question:"¿Qué error SQL de violación de clave duplicada se produce habitualmente al insertar un email único existente?", options:["SQLSTATE 23000 (Integrity constraint violation)","SQLSTATE 42000 (Syntax error), concepto diferente al que se describe en esta pregunta","SQLSTATE 08001 (Connection failure)","SQLSTATE 00000, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"El código estándar SQLSTATE 23000 cubre violaciones de restricciones de integridad (unique, primary key, foreign key).", noShuffle:false },
  { concept_id:"dwes_u4_q39", unit:4, question:"¿Qué método de PDOStatement devuelve el código de estado SQL estándar tras ejecutar una consulta?", options:["$stmt->errorCode() y $stmt->errorInfo()","$stmt->getError(), concepto diferente al que se describe en esta pregunta","$stmt->status(), concepto diferente al que se describe en esta pregunta","$stmt->sqlError(), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"errorCode() devuelve el código SQLSTATE de 5 caracteres, y errorInfo() un array con detalles del driver.", noShuffle:false },
  { concept_id:"dwes_u4_q40", unit:4, question:"¿Por qué es recomendable utilizar un patrón Singleton o inyección de dependencias para el objeto PDO?", options:["Porque PDO no admite más de una instancia por ordenador, concepto diferente al que se describe en esta pregunta","Para reutilizar una única conexión a la base de datos durante el ciclo de vida de la petición, evitando agotar el pool de sockets del SGBD","Para cifrar las consultas, concepto diferente al que se describe en esta pregunta","Porque PDO se borra al salir de funciones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Abrir múltiples conexiones PDO en una sola petición sobrecarga el servidor de base de datos y degrada gravemente el rendimiento.", noShuffle:false },
  { concept_id:"dwes_u4_q41", unit:4, question:"¿Qué nivel de aislamiento de transacciones previene lecturas sucias (dirty reads)?", options:["Read Uncommitted, concepto diferente al que se describe en esta pregunta","Read Committed (y niveles superiores como Repeatable Read y Serializable)","No Isolation, concepto diferente al que se describe en esta pregunta","None, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Read Committed garantiza que una transacción solo puede leer datos que ya han sido confirmados formalmente por otras transacciones.", noShuffle:false },
  { concept_id:"dwes_u4_q42", unit:4, question:"¿Qué ventaja ofrece PDO::FETCH_OBJ frente a FETCH_ASSOC?", options:["Permite acceder a los campos mediante sintaxis de objeto: $fila->nombre en lugar de $fila['nombre']","Es diez veces más rápido","Consume menos memoria RAM siempre","Convierte los números a objetos"], correct:0, explanation:"FETCH_OBJ devuelve un objeto de la clase estándar stdClass cuyas propiedades públicas coinciden con las columnas consultadas.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 5 — Sesiones, Cookies y Autenticación
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwes_u5_q1", unit:5, question:"¿Qué función debe llamarse obligatoriamente antes de acceder a la variable $_SESSION en PHP?", options:["init_session();","session_start();","start_session();","session_open();"], correct:1, explanation:"session_start() inicializa una nueva sesión o reanuda la existente leyendo la cookie identificadora PHPSESSID.", noShuffle:false },
  { concept_id:"dwes_u5_q2", unit:5, question:"¿Dónde se almacenan por defecto los datos guardados en $_SESSION?", options:["En el navegador del cliente, concepto diferente al que se describe en esta pregunta","En archivos temporales en el disco duro del servidor (o en Redis/Memcached según configuración)","En la base de datos de MySQL automáticamente, concepto diferente al que se describe en esta pregunta","En la memoria RAM del cliente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"A diferencia de las cookies, los datos de sesión residen en el servidor; el cliente solo posee un identificador opaco (Session ID).", noShuffle:false },
  { concept_id:"dwes_u5_q3", unit:5, question:"¿Cómo se establece una cookie en el navegador desde PHP?", options:["cookie_set('nombre', 'valor');","setcookie('nombre', 'valor', $opciones);","$_COOKIE['nombre'] = 'valor';","header_cookie('nombre', 'valor');"], correct:1, explanation:"setcookie() envía la cabecera HTTP Set-Cookie al navegador. Asignar directamente a $_COOKIE solo modifica el array en memoria, no el cliente.", noShuffle:false },
  { concept_id:"dwes_u5_q4", unit:5, question:"¿Por qué debe llamarse a setcookie() y session_start() antes de cualquier salida HTML?", options:["Porque consumen mucha memoria, concepto diferente al que se describe en esta pregunta","Porque envían cabeceras HTTP (Set-Cookie) y estas deben transmitirse antes de que comience el cuerpo de la respuesta","Porque cancelan los scripts JavaScript, concepto diferente al que se describe en esta pregunta","Para validar el certificado SSL, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Cualquier espacio o echo previo genera el error 'Headers already sent', impidiendo enviar nuevas cookies de sesión.", noShuffle:false },
  { concept_id:"dwes_u5_q5", unit:5, question:"¿Qué función cumple el flag 'HttpOnly' en una cookie?", options:["Indica que la cookie solo funciona en servidores Apache, concepto diferente al que se describe en esta pregunta","Impide que los scripts del lado del cliente (JavaScript / document.cookie) puedan leer la cookie, mitigando robos de sesión por ataques XSS","Obliga a que la cookie solo se envíe por HTTPS, concepto diferente al que se describe en esta pregunta","Borra la cookie al cerrar el navegador, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"HttpOnly protege el identificador de sesión haciendo que el navegador no lo exponga a la API de JavaScript.", noShuffle:false },
  { concept_id:"dwes_u5_q6", unit:5, question:"¿Qué función cumple el flag 'Secure' en una cookie?", options:["Cifra el contenido con AES-256, concepto diferente al que se describe en esta pregunta","Garantiza que la cookie solo se transmitirá a través de conexiones seguras cifradas con HTTPS","Exige autenticación en dos pasos, concepto diferente al que se describe en esta pregunta","Bloquea el acceso a robots, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El flag Secure previene la interceptación de cookies en texto claro frente a redes no confiables o ataques Man-in-the-Middle.", noShuffle:false },
  { concept_id:"dwes_u5_q7", unit:5, question:"¿Qué función cumple el atributo 'SameSite' (Strict / Lax) en una cookie?", options:["Evita que la cookie se duplique en el mismo sitio, concepto diferente al que se describe en esta pregunta","Protege contra ataques CSRF (Cross-Site Request Forgery) impidiendo que la cookie se envíe en peticiones originadas en sitios de terceros","Garantiza que la cookie funcione en todos los subdominios, concepto diferente al que se describe en esta pregunta","Sincroniza la cookie con la base de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"SameSite=Lax/Strict restringe cuándo los navegadores adjuntan la cookie en peticiones cross-origin, neutralizando ataques CSRF.", noShuffle:false },
  { concept_id:"dwes_u5_q8", unit:5, question:"¿Cómo se destruye completamente una sesión en PHP (Logout seguro)?", options:["session_destroy() únicamente, concepto diferente al que se describe en esta pregunta","session_unset(); session_destroy(); y borrar la cookie de sesión en el cliente caducándola con setcookie()","$_SESSION = null;, concepto diferente al que se describe en esta pregunta","cerrar el navegador, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Para un logout robusto: vaciar $_SESSION, llamar a session_destroy() y expirar la cookie de sesión (PHPSESSID) en el cliente.", noShuffle:false },
  { concept_id:"dwes_u5_q9", unit:5, question:"¿Qué función nativa de PHP se utiliza para generar un hash seguro de una contraseña?", options:["md5($pass), concepto diferente al que se describe en esta pregunta","sha1($pass), concepto diferente al que se describe en esta pregunta","password_hash($pass, PASSWORD_BCRYPT o PASSWORD_DEFAULT)","crypt_sha256($pass), concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"password_hash() aplica algoritmos lentos y resistentes a fuerza bruta (Bcrypt, Argon2) generando un salt criptográfico automático.", noShuffle:false },
  { concept_id:"dwes_u5_q10", unit:5, question:"¿Por qué nunca se deben almacenar contraseñas usando MD5 o SHA-1?", options:["Porque ocupan demasiado espacio en disco, concepto diferente al que se describe en esta pregunta","Porque son algoritmos criptográficos rotos, extremadamente rápidos de romper mediante tablas Rainbow y fuerza bruta con GPU moderna","Porque PHP los ha eliminado del lenguaje, concepto diferente al que se describe en esta pregunta","Porque no admiten caracteres Unicode, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"MD5 y SHA-1 se calculan en nanosegundos por intento, lo que permite a atacantes descifrar millones de contraseñas por segundo.", noShuffle:false },
  { concept_id:"dwes_u5_q11", unit:5, question:"¿Qué función nativa de PHP comprueba si una contraseña en texto plano coincide con su hash almacenado?", options:["password_check($pass, $hash)","password_verify($pass, $hash)","$hash == password_hash($pass)","verify_credentials($pass, $hash)"], correct:1, explanation:"password_verify() verifica la coincidencia en tiempo constante, protegiendo contra ataques de temporización (timing attacks).", noShuffle:false },
  { concept_id:"dwes_u5_q12", unit:5, question:"¿Qué función determina si un hash almacenado necesita ser recalculado porque han cambiado los factores de coste o algoritmos?", options:["password_needs_rehash($hash, PASSWORD_DEFAULT)","password_rehash(), concepto diferente al que se describe en esta pregunta","check_hash_cost(), concepto diferente al que se describe en esta pregunta","update_hash(), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"password_needs_rehash() permite actualizar automáticamente la seguridad de los hashes cuando el usuario hace login con credenciales válidas.", noShuffle:false },
  { concept_id:"dwes_u5_q13", unit:5, question:"¿Qué ataque previene la función session_regenerate_id(true)?", options:["Inyección SQL, concepto diferente al que se describe en esta pregunta","Fijación de sesión (Session Fixation) regenerando el identificador tras iniciar sesión con éxito","Denegación de servicio, concepto diferente al que se describe en esta pregunta","Cross-Site Scripting, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Session Fixation ocurre cuando un atacante impone un ID conocido a la víctima; regenerar el ID tras el login invalida el anterior.", noShuffle:false },
  { concept_id:"dwes_u5_q14", unit:5, question:"¿Cómo se expira o borra una cookie en el cliente desde PHP?", options:["delete_cookie('nombre');, concepto diferente al que se describe en esta pregunta","setcookie('nombre', '', time() - 3600);","unset($_COOKIE['nombre']); exclusivamente","$_COOKIE['nombre'] = '';"], correct:1, explanation:"Para eliminar una cookie del navegador se debe volver a enviar con una fecha de expiración en el pasado (ej: time() - 3600).", noShuffle:false },
  { concept_id:"dwes_u5_q15", unit:5, question:"¿Cuál es la función del 'Salt' en el almacenamiento de contraseñas?", options:["Cifrar la clave con una contraseña simétrica, concepto diferente al que se describe en esta pregunta","Una secuencia pseudoaleatoria única concatenada a la contraseña antes de hashear para evitar ataques de tablas Rainbow precalculadas","Abreviar el tamaño de la cadena resultante, concepto diferente al que se describe en esta pregunta","Comprimir el hash, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El salt garantiza que dos usuarios con la misma contraseña tengan hashes completamente diferentes e imposibles de buscar en diccionarios previos.", noShuffle:false },
  { concept_id:"dwes_u5_q16", unit:5, question:"¿Qué es el Session Hijacking (Secuestro de sesión)?", options:["Cuando el servidor borra las sesiones, concepto diferente al que se describe en esta pregunta","Cuando un atacante obtiene el Session ID de un usuario legítimo y lo utiliza para suplantar su identidad activa","Cuando un usuario olvida su contraseña, concepto diferente al que se describe en esta pregunta","Cuando se caen los servidores de bases de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si el atacante intercepta la cookie de sesión (vía XSS o red insegura), el servidor no puede distinguirlo del usuario real.", noShuffle:false },
  { concept_id:"dwes_u5_q17", unit:5, question:"¿Cómo se mitiga el Session Hijacking en aplicaciones PHP?", options:["Usando HTTPS exclusivamente, cookies HttpOnly, Secure, regenerando ID y comprobando cambios de User-Agent o expiración por inactividad","Eliminando las sesiones por completo, concepto diferente al que se describe en esta pregunta","Permitiendo sesiones infinitas, concepto diferente al que se describe en esta pregunta","Usando variables globales, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"La combinación de HTTPS, flags de cookies seguras y regeneración continua minimiza drásticamente las ventanas de robo.", noShuffle:false },
  { concept_id:"dwes_u5_q18", unit:5, question:"¿Qué función de PHP devuelve el Session ID actual?", options:["session_id()","get_session_id()","$_SESSION['id']","session_token()"], correct:0, explanation:"session_id() devuelve el identificador alfanumérico actual (o establece uno nuevo si se le pasa como parámetro antes de session_start).", noShuffle:false },
  { concept_id:"dwes_u5_q19", unit:5, question:"¿Qué hace la función session_unset()?", options:["Destruye el archivo en disco del servidor, concepto diferente al que se describe en esta pregunta","Libera y borra todas las variables registradas actualmente en el array $_SESSION","Desconecta la base de datos, concepto diferente al que se describe en esta pregunta","Cierra la pestaña del navegador, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"session_unset() vacía en memoria todas las variables del array de sesión, dejando $_SESSION como un array vacío.", noShuffle:false },
  { concept_id:"dwes_u5_q20", unit:5, question:"¿Cómo se implementa una política de expiración de sesión por inactividad en PHP?", options:["En php.ini exclusivamente con session.gc_maxlifetime","Guardando un timestamp en $_SESSION['ultimo_acceso'] y verificando en cada petición si la diferencia supera el tiempo límite","Con un setTimeout() en JavaScript únicamente","Las sesiones en PHP nunca caducan"], correct:1, explanation:"Almacenar $_SESSION['ultimo_acceso'] = time(); permite comprobar: if (time() - $_SESSION['ultimo_acceso'] > 900) { logout(); }", noShuffle:false },
  { concept_id:"dwes_u5_q21", unit:5, question:"¿Qué es el ataque CSRF (Cross-Site Request Forgery)?", options:["Robar contraseñas mediante keylogger, concepto diferente al que se describe en esta pregunta","Engañar al navegador autenticado de una víctima para que ejecute peticiones no deseadas contra una aplicación web aprovechando sus cookies activas","Modificar el código fuente de PHP, concepto diferente al que se describe en esta pregunta","Inyectar scripts SQL en la barra de direcciones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Un sitio malicioso incluye una petición forzada (ej: transferir fondos) que el navegador envía adjuntando las cookies del usuario legítimo.", noShuffle:false },
  { concept_id:"dwes_u5_q22", unit:5, question:"¿Cuál es la técnica estándar para prevenir ataques CSRF en formularios web?", options:["Desactivar JavaScript, concepto diferente al que se describe en esta pregunta","Generar un token pseudoaleatorio único por sesión en el servidor (CSRF Token), incluirlo en un campo oculto del formulario y validarlo al recibir el POST","Usar siempre método GET, concepto diferente al que se describe en esta pregunta","Pedir la contraseña en cada campo es una accion que no define correctamente este concepto"], correct:1, explanation:"El Synchronizer Token Pattern exige que cada formulario incluya un token secreto almacenado en sesión que el atacante no puede leer ni predecir.", noShuffle:false },
  { concept_id:"dwes_u5_q23", unit:5, question:"¿Qué función criptográficamente segura se debe usar en PHP para generar tokens CSRF o claves aleatorias?", options:["rand(), concepto diferente al que se describe en esta pregunta","mt_rand(), concepto diferente al que se describe en esta pregunta","random_bytes() o bin2hex(random_bytes(32))","uniqid(), concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"random_bytes() y random_int() utilizan los generadores de entropía del sistema operativo (CSPRNG), a diferencia de rand() o mt_rand().", noShuffle:false },
  { concept_id:"dwes_u5_q24", unit:5, question:"¿Qué algoritmo de hashing de contraseñas de última generación es soportado nativamente en PHP con PASSWORD_ARGON2ID?", options:["MD5, concepto diferente al que se describe en esta pregunta","SHA-256, concepto diferente al que se describe en esta pregunta","Argon2id (ganador del Password Hashing Competition, resistente a ataques de memoria y GPU)","PBKDF1, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"Argon2id combina resistencia frente a ataques de canal lateral con alta demanda de memoria y computación, superando a Bcrypt.", noShuffle:false },
  { concept_id:"dwes_u5_q25", unit:5, question:"¿Qué directiva de configuración en php.ini impide que PHP acepte IDs de sesión pasados por URL (query string)?", options:["session.use_cookies = 1, concepto diferente al que se describe en esta pregunta","session.use_only_cookies = 1 y session.use_trans_sid = 0","session.strict_mode = 0, concepto diferente al que se describe en esta pregunta","session.no_url = 1, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permitir IDs de sesión en la URL (trans_sid) es una grave brecha de seguridad porque los enlaces se filtran en historiales y cabeceras Referer.", noShuffle:false },
  { concept_id:"dwes_u5_q26", unit:5, question:"¿Qué es el 'Timing Attack' al comparar cadenas de contraseñas o tokens y cómo se evita?", options:["Ataques que envían peticiones a gran velocidad, concepto diferente al que se describe en esta pregunta","Un atacante deduce caracteres midiendo variaciones microscópicas en el tiempo de respuesta del operador ==; se evita con hash_equals()","Ataques que alteran el reloj del sistema, concepto diferente al que se describe en esta pregunta","Se evita usando sleep(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"hash_equals($conocido, $usuario) compara cadenas en tiempo constante, evitando que el atacante adivine prefijos carácter a carácter.", noShuffle:false },
  { concept_id:"dwes_u5_q27", unit:5, question:"¿Qué tamaño máximo aproximado de almacenamiento admite una cookie en los navegadores estándar?", options:["No tiene límite, aunque en otros contextos puede tener cierta relevancia","Aproximadamente 4 KB por cookie y un máximo de ~50 cookies por dominio","10 MB, concepto diferente al que se describe en esta pregunta","1 GB, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las cookies están limitadas a ~4096 bytes. Para volúmenes mayores se utiliza almacenamiento en servidor o Web Storage.", noShuffle:false },
  { concept_id:"dwes_u5_q28", unit:5, question:"¿Qué ocurre si no se llama a session_write_close() en scripts PHP concurrentes de larga duración?", options:["Se pierde la base de datos, concepto diferente al que se describe en esta pregunta","El archivo de sesión permanece bloqueado por el primer script","Se borran las cookies, concepto diferente al que se describe en esta pregunta","Se cancela el proceso, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"PHP bloquea el fichero de sesión para evitar condiciones de carrera. session_write_close() guarda y libera el bloqueo anticipadamente.", noShuffle:false },
  { concept_id:"dwes_u5_q29", unit:5, question:"¿Cómo se accede a una cookie enviada por el navegador llamada 'preferencias'?", options:["$preferencias","$_COOKIE['preferencias']","$_SESSION['preferencias']","cookie('preferencias')"], correct:1, explanation:"El array superglobal $_COOKIE almacena todas las cookies recibidas en la petición HTTP actual.", noShuffle:false },
  { concept_id:"dwes_u5_q30", unit:5, question:"¿Por qué no se debe almacenar información confidencial (como roles de usuario o contraseñas) en cookies sin firmar/cifrar?", options:["Porque el cliente puede inspeccionar y modificar libremente el valor de las cookies en las herramientas de desarrollo de su navegador","Porque caducan muy rápido, concepto diferente al que se describe en esta pregunta","Porque las cookies no admiten texto, concepto diferente al que se describe en esta pregunta","Porque ocupan demasiado ancho de banda, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Las cookies residen en el cliente. Si guardas 'rol=admin' en una cookie, cualquier usuario puede cambiarlo y escalar privilegios.", noShuffle:false },
  { concept_id:"dwes_u5_q31", unit:5, question:"¿Qué es la autenticación 'Remember Me' (Recordarme) segura?", options:["Guardar la contraseña en una cookie, concepto diferente al que se describe en esta pregunta","Almacenar un selector público y un token pseudoaleatorio hasheado en la base de datos con expiración prolongada en una cookie HttpOnly","Mantener la sesión de PHP abierta para siempre, concepto diferente al que se describe en esta pregunta","Guardar el ID de usuario en localStorage, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El patrón de tokens persistentes (selector + validator hasheado) permite recordar al usuario sin comprometer su contraseña permanente.", noShuffle:false },
  { concept_id:"dwes_u5_q32", unit:5, question:"¿Qué parámetro de setcookie() define los directorios donde la cookie es válida?", options:["domain","path","secure","httponly"], correct:1, explanation:"path='/admin' restringirá el envío de la cookie únicamente a rutas bajo /admin. Por defecto '/' cubre todo el dominio.", noShuffle:false },
  { concept_id:"dwes_u5_q33", unit:5, question:"¿Qué directiva de php.ini permite delegar el almacenamiento de sesiones en un servidor Redis en memoria?", options:["session.save_handler = redis y session.save_path = 'tcp://127.0.0.1:6379'","session.backend = 'redis', concepto diferente al que se describe en esta pregunta","session.driver = 'memory', concepto diferente al que se describe en esta pregunta","session.redis_enable = 1, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Almacenar sesiones en Redis o Memcached permite compartir sesiones horizontalmente entre múltiples servidores web balanceados.", noShuffle:false },
  { concept_id:"dwes_u5_q34", unit:5, question:"¿Qué parámetro en password_hash() con Bcrypt regula la dificultad computacional y el tiempo de cálculo?", options:["'cost' => 12","'rounds' => 100","'difficulty' => 'high'","'salt_length' => 64"], correct:0, explanation:"El parámetro 'cost' (por defecto 10 o 12) incrementa exponencialmente el trabajo y tiempo requerido por el algoritmo, dificultando la fuerza bruta.", noShuffle:false },
  { concept_id:"dwes_u5_q35", unit:5, question:"¿Qué representa el prefijo '$2y$' en una cadena de hash generada por password_hash()?", options:["El algoritmo de cifrado DES, concepto que se aplica en un contexto distinto","El identificador del algoritmo Bcrypt resistente a errores históricos de codificación","El nombre del usuario, concepto diferente al que se describe en esta pregunta","La clave pública, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"$2y$ indica una variante segura y corregida de Bcrypt implementada en PHP.", noShuffle:false },
  { concept_id:"dwes_u5_q36", unit:5, question:"¿Qué es el principio de defensa en profundidad en autenticación?", options:["Usar contraseñas largas únicamente, concepto diferente al que se describe en esta pregunta","Implementar múltiples capas de seguridad superpuestas: rate limiting","Ocultar el código fuente del servidor, concepto diferente al que se describe en esta pregunta","Usar tres bases de datos diferentes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si una capa de defensa falla o es vulnerada, otras capas independientes continúan protegiendo el sistema.", noShuffle:false },
  { concept_id:"dwes_u5_q37", unit:5, question:"¿Qué función de PHP permite configurar las opciones predeterminadas de la cookie de sesión (lifetime, path, domain, secure, httponly, samesite)?", options:["session_set_cookie_params($opciones)","set_session_defaults(), concepto diferente al que se describe en esta pregunta","config_session(), concepto diferente al que se describe en esta pregunta","cookie_options(), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"session_set_cookie_params(['lifetime' => 0, 'secure' => true, 'httponly' => true, 'samesite' => 'Lax']) protege la sesión antes de session_start().", noShuffle:false },
  { concept_id:"dwes_u5_q38", unit:5, question:"¿Cómo se implementa un mecanismo de Rate Limiting para prevenir ataques de fuerza bruta en el login?", options:["Contando intentos fallidos asociados a la IP o cuenta en BD/Redis y bloqueando temporalmente tras superar un umbral","Desconectando el servidor, concepto diferente al que se describe en esta pregunta","Pidiendo al usuario que espere un segundo, concepto diferente al que se describe en esta pregunta","Bloqueando todas las IPs de ese país, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"El rate limiting limita la frecuencia de peticiones de login por IP o nombre de usuario, neutralizando los diccionarios automáticos.", noShuffle:false },
  { concept_id:"dwes_u5_q39", unit:5, question:"¿Qué cabecera de respuesta HTTP se envía al cliente cuando se ejecuta setcookie() en PHP?", options:["Get-Cookie","Set-Cookie","Cookie-Accept","Cookie-Header"], correct:1, explanation:"La cabecera 'Set-Cookie: nombre=valor; Path=/; Secure; HttpOnly' instruye al navegador para guardar la cookie.", noShuffle:false },
  { concept_id:"dwes_u5_q40", unit:5, question:"¿Qué es 2FA (Autenticación de Doble Factor) basada en TOTP?", options:["Introducir la contraseña dos veces, concepto diferente al que se describe en esta pregunta","Requerir un factor de conocimiento (contraseña) y un factor de posesión (código temporal de 6 dígitos generado por una app como Google Authenticator)","Tener dos usuarios administradores, concepto diferente al que se describe en esta pregunta","Confirmar la cuenta por SMS únicamente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"TOTP (Time-based One-Time Password) genera códigos criptográficos sincronizados cada 30 segundos usando una clave secreta compartida.", noShuffle:false },
  { concept_id:"dwes_u5_q41", unit:5, question:"¿Qué ocurre si un usuario desactiva las cookies en su navegador y el servidor usa sesiones estándar de PHP?", options:["El servidor guarda los datos en su disco igualmente, pero no puede asociar al usuario con su sesión en peticiones posteriores","La aplicación web funciona más rápido, concepto diferente al que se describe en esta pregunta","El servidor lanza un Fatal Error, concepto diferente al que se describe en esta pregunta","Se transfieren las cookies a la BIOS, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Sin cookies, el cliente no reenvía el PHPSESSID, por lo que cada petición es vista por PHP como un usuario nuevo sin datos previos.", noShuffle:false },
  { concept_id:"dwes_u5_q42", unit:5, question:"¿Por qué se debe invalidar y regenerar la sesión inmediatamente tras un cambio de contraseña o de correo electrónico?", options:["Para vaciar la memoria RAM, concepto diferente al que se describe en esta pregunta","Para expulsar y desautenticar cualquier otra sesión activa que un atacante pudiera tener abierta de forma concurrente","Para actualizar el reloj, concepto diferente al que se describe en esta pregunta","Es un requisito legal, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite asegurar que si la cuenta fue comprometida, el atacante pierda inmediatamente el acceso secuestrado tras el restablecimiento.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 6 — POO y Frameworks MVC en PHP
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwes_u6_q1", unit:6, question:"¿Cómo se define una clase y su constructor en PHP moderno?", options:["class Coche { function Coche() {} }","class Coche { public function __construct(private string $marca) {} }","create class Coche { init() {} }","class Coche extends Object {}"], correct:1, explanation:"__construct es el constructor mágico de PHP. PHP 8 admite 'Constructor Property Promotion' para declarar y asignar propiedades en la firma.", noShuffle:false },
  { concept_id:"dwes_u6_q2", unit:6, question:"¿Qué visibilidad permite que un atributo o método sea accesible solo desde la propia clase y desde las clases que heredan de ella?", options:["private","public","protected","internal"], correct:2, explanation:"'protected' limita el acceso a la clase declarante y a su jerarquía de clases descendientes. 'private' solo a la propia clase.", noShuffle:false },
  { concept_id:"dwes_u6_q3", unit:6, question:"¿Cómo se llama al constructor de la clase padre en una subclase PHP?", options:["parent::__construct($args);","super($args);","base::__construct($args);","Parent::init($args);"], correct:0, explanation:"'parent::__construct()' invoca explícitamente el constructor de la superclase mediante el operador de resolución de ámbito (::).", noShuffle:false },
  { concept_id:"dwes_u6_q4", unit:6, question:"¿Qué es una interfaz (interface) en PHP?", options:["Una vista gráfica HTML, concepto diferente al que se describe en esta pregunta","Un contrato que declara métodos públicos abstractos que cualquier clase que la implemente (implements) está obligada a definir","Una clase que no puede tener métodos, concepto diferente al que se describe en esta pregunta","Un archivo de configuración, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las interfaces definen qué métodos debe poseer una clase sin implementar su lógica, permitiendo polimorfismo puro e inversión de dependencias.", noShuffle:false },
  { concept_id:"dwes_u6_q5", unit:6, question:"¿Qué es un 'Trait' en PHP?", options:["Un tipo especial de interfaz, concepto diferente al que se describe en esta pregunta","Un mecanismo de reutilización de código en lenguajes de herencia simple que permite incluir métodos en múltiples clases independientes mediante 'use'","Un destructor de objetos, concepto diferente al que se describe en esta pregunta","Un plugin de Apache, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"PHP solo admite herencia simple (una sola clase base). Los traits permiten compartir implementación horizontalmente sin duplicar código.", noShuffle:false },
  { concept_id:"dwes_u6_q6", unit:6, question:"¿Qué función cumplen los Namespaces (espacios de nombres) en PHP?", options:["Dar nombre a las variables del sistema, concepto diferente al que se describe en esta pregunta","Organizar el código en paquetes lógicos y evitar colisiones de nombres entre clases o librerías de terceros","Definir nombres de bases de datos, concepto diferente al que se describe en esta pregunta","Crear subdominios web, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"namespace MiApp\\Modelos; resuelve conflictos de nombres (ej: dos clases llamadas Usuario) y organiza las carpetas.", noShuffle:false },
  { concept_id:"dwes_u6_q7", unit:6, question:"¿Qué estándar de PHP-FIG (PSR) define las reglas para la carga automática de clases (Autoloading)?", options:["PSR-1","PSR-4","PSR-7","PSR-12"], correct:1, explanation:"PSR-4 describe la correspondencia entre los namespaces de las clases y las rutas físicas de directorios en el sistema de archivos.", noShuffle:false },
  { concept_id:"dwes_u6_q8", unit:6, question:"¿Qué herramienta es el gestor de dependencias estándar de facto para el ecosistema PHP?", options:["npm","pip","Composer","Bundler"], correct:2, explanation:"Composer gestiona librerías externas declaradas en composer.json y genera automáticamente el cargador 'vendor/autoload.php'.", noShuffle:false },
  { concept_id:"dwes_u6_q9", unit:6, question:"¿Cuáles son los tres componentes del patrón arquitectural MVC?", options:["MySQL, VirtualHost y CSS, concepto diferente al que se describe en esta pregunta","Modelo (Datos/Lógica), Vista (Interfaz/Presentación) y Controlador (Flujo/Coordinación)","Módulos, Variables y Constantes, concepto diferente al que se describe en esta pregunta","Main, View y Core, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"MVC separa la responsabilidad de acceso a datos (Modelo), la representación visual (Vista) y la lógica de control y respuesta (Controlador).", noShuffle:false },
  { concept_id:"dwes_u6_q10", unit:6, question:"¿Cuál es la responsabilidad principal del 'Controlador' en MVC?", options:["Escribir código SQL directo, concepto diferente al que se describe en esta pregunta","Recibir la petición HTTP, interactuar con el Modelo para obtener o alterar datos y seleccionar la Vista adecuada para responder","Renderizar estilos CSS, concepto diferente al que se describe en esta pregunta","Configurar el cortafuegos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El controlador actúa como director de orquesta: interpreta la acción solicitada, delega la lógica al modelo y pasa datos a la vista.", noShuffle:false },
  { concept_id:"dwes_u6_q11", unit:6, question:"¿Cuál es la responsabilidad principal del 'Modelo' en MVC?", options:["Desplegar formularios en pantalla, concepto diferente al que se describe en esta pregunta","Encapsular los datos, las reglas de negocio, validaciones y la persistencia en base de datos","Procesar cabeceras HTTP, concepto diferente al que se describe en esta pregunta","Gestionar la sesión de usuario, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El modelo representa el estado de la aplicación y la lógica de dominio, independientemente de cómo se muestre en pantalla.", noShuffle:false },
  { concept_id:"dwes_u6_q12", unit:6, question:"¿Qué es el patrón 'Front Controller' en frameworks PHP como Laravel o Symfony?", options:["Un controlador solo para el frontend de JS, concepto diferente al que se describe en esta pregunta","Un único archivo de entrada por el que pasan absolutamente todas las peticiones para ser enrutadas","El primer controlador de la base de datos, concepto diferente al que se describe en esta pregunta","Un plugin de CSS, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El Front Controller centraliza la inicialización, configuración, seguridad y enrutamiento antes de despachar al controlador específico.", noShuffle:false },
  { concept_id:"dwes_u6_q13", unit:6, question:"¿Qué función cumple el 'Router' (Enrutador) en una arquitectura web moderna?", options:["Conectar los cables de red física, concepto diferente al que se describe en esta pregunta","Mapear la URL y el método HTTP de la petición entrante a la acción y controlador correspondiente","Redirigir a los usuarios al login, concepto diferente al que se describe en esta pregunta","Traducir texto a otros idiomas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El router analiza peticiones como 'GET /articulos/42' y las delega al método ArticuloController::mostrar(42).", noShuffle:false },
  { concept_id:"dwes_u6_q14", unit:6, question:"¿Qué es un ORM (Object-Relational Mapping)?", options:["Un tipo de base de datos no relacional, concepto diferente al que se describe en esta pregunta","Una capa de abstracción que mapea tablas relacionales a clases y filas a objetos en el código","Un optimizador de memoria RAM, concepto diferente al que se describe en esta pregunta","Un servidor de correo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Un ORM permite interactuar con la base de datos utilizando objetos y métodos OOP (ej: $usuario->save()) sin escribir SQL manual.", noShuffle:false },
  { concept_id:"dwes_u6_q15", unit:6, question:"¿Cuál es la diferencia entre el patrón Active Record y el patrón Data Mapper en persistencia?", options:["No hay diferencia, aunque algunos enfoques establecen matices al respecto","En Active Record la entidad agrupa datos y métodos de persistencia ($user->save()); en Data Mapper la entidad es pura y un repositorio independiente gestiona la BD ($em->persist($user))","Data Mapper solo sirve para bases NoSQL, concepto diferente al que se describe en esta pregunta","Active Record es exclusivo de Java, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Active Record (ej: Eloquent de Laravel) es más simple y directo. Data Mapper (ej: Doctrine de Symfony) separa estrictamente el dominio de la persistencia.", noShuffle:false },
  { concept_id:"dwes_u6_q16", unit:6, question:"¿Qué es la Inyección de Dependencias (Dependency Injection)?", options:["Una técnica de hackeo malicioso, concepto diferente al que se describe en esta pregunta","Un patrón de diseño donde los objetos reciben sus dependencias desde el exterior (vía constructor o setter) en lugar de instanciarlas internamente con 'new'","Instalar paquetes con Composer es una accion que no define correctamente este concepto","Cargar extensiones en php.ini, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Desacopla componentes facilitando el testing unitario con mocks y cumpliendo el principio de Inversión de Dependencias (SOLID).", noShuffle:false },
  { concept_id:"dwes_u6_q17", unit:6, question:"¿Qué es un contenedor de servicios (Service Container / DI Container)?", options:["Un contenedor Docker en Linux, concepto diferente al que se describe en esta pregunta","Un componente centralizado del framework que se encarga de instanciar","Una base de datos de servicios web, concepto diferente al que se describe en esta pregunta","Un pool de conexiones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El contenedor DI analiza las firmas de las clases mediante reflexión y crea automáticamente las instancias necesarias.", noShuffle:false },
  { concept_id:"dwes_u6_q18", unit:6, question:"¿Qué significa la palabra clave 'final' aplicada a una clase o método en PHP?", options:["Que es el último método del archivo, concepto diferente al que se describe en esta pregunta","Que la clase no puede ser heredada, o que el método no puede ser sobrescrito por ninguna subclase","Que se ejecuta al destruir el objeto, concepto diferente al que se describe en esta pregunta","Que no puede tener constructor, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"'final class Servicio' impide la extensión por herencia, garantizando la inmutabilidad de su comportamiento.", noShuffle:false },
  { concept_id:"dwes_u6_q19", unit:6, question:"¿Qué significa una clase declarada como 'abstract'?", options:["Una clase sin propiedades, concepto diferente al que se describe en esta pregunta","Una clase que no se puede instanciar directamente con 'new' y está diseñada para servir como plantilla base de subclases concretas","Una clase virtual en memoria caché, concepto diferente al que se describe en esta pregunta","Una clase anónima, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las clases abstractas pueden contener métodos implementados y métodos abstractos (sin cuerpo) que las hijas deben desarrollar obligatoriamente.", noShuffle:false },
  { concept_id:"dwes_u6_q20", unit:6, question:"¿Qué método mágico de PHP se invoca automáticamente al intentar convertir un objeto a cadena de texto?", options:["__toText()","__toString()","__cast()","__print()"], correct:1, explanation:"public function __toString(): string permite que 'echo $objeto;' devuelva una representación en string legible.", noShuffle:false },
  { concept_id:"dwes_u6_q21", unit:6, question:"¿Qué métodos mágicos de PHP interceptan la lectura y escritura de propiedades inexistentes o inaccesibles?", options:["__read() y __write(), concepto diferente al que se describe en esta pregunta","__get($nombre) y __set($nombre, $valor)","__pull() y __push(), concepto diferente al que se describe en esta pregunta","__property_get(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"__get() y __set() permiten implementar sobrecarga de propiedades dinámicas y lazy-loading.", noShuffle:false },
  { concept_id:"dwes_u6_q22", unit:6, question:"¿Qué método mágico se invoca cuando se intenta llamar a un objeto como si fuera una función?", options:["__invoke()","__call()","__execute()","__run()"], correct:0, explanation:"public function __invoke(...$args) convierte instancias de clase en callables directos: $miObjeto($param).", noShuffle:false },
  { concept_id:"dwes_u6_q23", unit:6, question:"¿Qué método mágico de PHP se ejecuta al clonar un objeto con la palabra clave 'clone'?", options:["__copy()","__clone()","__duplicate()","__replicate()"], correct:1, explanation:"__clone() permite personalizar la clonación profunda (deep copy) de propiedades que contengan referencias a otros objetos.", noShuffle:false },
  { concept_id:"dwes_u6_q24", unit:6, question:"¿Qué es un Middleware en el contexto de frameworks web?", options:["Un controlador de base de datos, concepto diferente al que se describe en esta pregunta","Una capa de software intermedia por la que pasa la petición HTTP antes de llegar al controlador","El hardware entre cliente y servidor, concepto diferente al que se describe en esta pregunta","Un motor de plantillas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los middlewares forman una tubería (pipeline o cebolla) que examina o altera peticiones y respuestas globalmente.", noShuffle:false },
  { concept_id:"dwes_u6_q25", unit:6, question:"¿Qué motor de plantillas para vistas es característico del framework Laravel?", options:["Twig","Blade","Smarty","Pug"], correct:1, explanation:"Blade compila plantillas legibles (.blade.php) a código PHP plano eficiente con directivas como @if, @foreach y @extends.", noShuffle:false },
  { concept_id:"dwes_u6_q26", unit:6, question:"¿Qué motor de plantillas es estándar en el framework Symfony?", options:["Blade","Twig","Mustache","Handlebars"], correct:1, explanation:"Twig es un motor de plantillas seguro, conciso y rápido que aísla estrictamente la lógica de presentación del código PHP.", noShuffle:false },
  { concept_id:"dwes_u6_q27", unit:6, question:"¿Qué significa el principio SOLID 'Single Responsibility Principle' (SRP)?", options:["Una clase solo puede tener un método, concepto diferente al que se describe en esta pregunta","Una clase debe tener una única razón para cambiar, es decir","Un programador solo trabaja en una clase, concepto diferente al que se describe en esta pregunta","Toda función debe retornar un solo valor, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"SRP establece que un módulo o clase debe especializarse en una sola tarea (ej: un repositorio no debe generar PDFs ni enviar emails).", noShuffle:false },
  { concept_id:"dwes_u6_q28", unit:6, question:"¿Qué significa el principio SOLID 'Open/Closed Principle' (OCP)?", options:["El código debe ser de código abierto pero cerrado a copias, concepto diferente al que se describe en esta pregunta","Las entidades de software deben estar abiertas para su extensión pero cerradas para su modificación","Los métodos deben cerrarse con llaves, concepto diferente al que se describe en esta pregunta","Abrir archivos y cerrarlos siempre, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Se debe poder añadir nueva funcionalidad (mediante herencia, composición o interfaces) sin reescribir ni romper el código ya probado existente.", noShuffle:false },
  { concept_id:"dwes_u6_q29", unit:6, question:"¿Qué es una migración de base de datos en un framework moderno?", options:["Pasar de MySQL a Oracle en caliente, concepto diferente al que se describe en esta pregunta","Archivos de control de versiones de código que describen cambios incrementales en el esquema de la base de datos (tablas, columnas, índices)","Exportar datos a CSV, concepto diferente al que se describe en esta pregunta","Crear backups automáticos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las migraciones permiten a equipos de desarrollo sincronizar y reproducir la estructura exacta de la base de datos de forma automatizada.", noShuffle:false },
  { concept_id:"dwes_u6_q30", unit:6, question:"¿Qué es un 'Seeder' en el contexto de bases de datos de frameworks?", options:["Un virus de base de datos, concepto diferente al que se describe en esta pregunta","Clases encargadas de poblar la base de datos con registros iniciales o ficticios (dummy/fake data) para pruebas y desarrollo","Un optimizador de índices, concepto diferente al que se describe en esta pregunta","Un sistema de replicación, que aunque es una herramienta util, no corresponde a esta definicion"], correct:1, explanation:"Los seeders (a menudo junto con librerías como Faker) insertan datos de prueba consistentes para testing y demostraciones.", noShuffle:false },
  { concept_id:"dwes_u6_q31", unit:6, question:"¿Qué son los 'Atributos' (Attributes) introducidos en PHP 8.0?", options:["Variables normales de una clase","Metadatos estructurados añadidos a clases, métodos o propiedades con sintaxis #[Atributo] que reemplazan a las anotaciones en phpDoc","Comentarios normales de código","Propiedades CSS de la vista"], correct:1, explanation:"Los atributos son metadatos nativos interpretables por el lenguaje en tiempo de ejecución mediante reflexión (muy usados para rutas y validaciones).", noShuffle:false },
  { concept_id:"dwes_u6_q32", unit:6, question:"¿Qué es una enumeración (Enum) en PHP 8.1+?", options:["Un bucle for especializado","Un tipo de dato especial que define un conjunto cerrado de valores posibles (ej: enum Estado: string { case ACTIVO = 'A'; })","Una lista enlazada","Un contador de líneas"], correct:1, explanation:"Los Enums proporcionan seguridad de tipos estricta para variables con estados o categorías predeterminadas.", noShuffle:false },
  { concept_id:"dwes_u6_q33", unit:6, question:"¿Qué es una propiedad 'readonly' en PHP 8.1+?", options:["Una propiedad sin visibilidad, concepto diferente al que se describe en esta pregunta","Una propiedad que solo puede inicializarse una única vez y no puede ser modificada posteriormente","Una propiedad privada, concepto diferente al que se describe en esta pregunta","Una constante global, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"readonly garantiza la inmutabilidad de los datos de un objeto tras su creación, previniendo alteraciones accidentales.", noShuffle:false },
  { concept_id:"dwes_u6_q34", unit:6, question:"¿Qué es el patrón 'Repository' en la capa de datos?", options:["Un repositorio Git dentro de la aplicación, concepto diferente al que se describe en esta pregunta","Una capa intermediaria que aísla la lógica de negocio del acceso directo a la BD, encapsulando las consultas de búsqueda y almacenamiento de entidades","Un directorio donde se guardan backups, concepto diferente al que se describe en esta pregunta","Una tabla de base de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El repositorio proporciona una interfaz de colección en memoria para acceder a datos (ej: $userRepo->findByEmail($email)) ocultando el SQL/ORM.", noShuffle:false },
  { concept_id:"dwes_u6_q35", unit:6, question:"¿Qué es el patrón 'Factory' en POO?", options:["Una clase que destruye objetos viejos, concepto diferente al que se describe en esta pregunta","Un patrón creacional que proporciona una interfaz o método para instanciar objetos sin acoplar el código a la clase concreta específica","Un plugin de compilación, concepto diferente al que se describe en esta pregunta","Un método de cifrado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El Factory centraliza la lógica compleja de construcción de instancias permitiendo sustituir implementaciones fácilmente.", noShuffle:false },
  { concept_id:"dwes_u6_q36", unit:6, question:"¿Cómo se comprueba si un objeto implementa una interfaz o hereda de una clase determinada en PHP?", options:["$obj->isA('MiClase')","$obj instanceof MiClase","is_class($obj, 'MiClase')","$obj->type == 'MiClase'"], correct:1, explanation:"El operador 'instanceof' comprueba relaciones de tipo en tiempo de ejecución, incluyendo herencia e interfaces.", noShuffle:false },
  { concept_id:"dwes_u6_q37", unit:6, question:"¿Qué hace la función spl_autoload_register() en PHP?", options:["Registra una función callback que el intérprete invocará automáticamente cuando se intente usar una clase no cargada previamente","Instala módulos en Apache, concepto diferente al que se describe en esta pregunta","Registra librerías en Composer, concepto diferente al que se describe en esta pregunta","Carga todas las clases a la vez en RAM, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Es el mecanismo nativo sobre el que se apoya Composer para el autoloading bajo demanda según PSR-4.", noShuffle:false },
  { concept_id:"dwes_u6_q38", unit:6, question:"¿Qué es una clase anónima en PHP?", options:["Una clase sin propiedades","Una clase definida al vuelo en el punto de uso sin asignarle un nombre formal mediante 'new class {}'","Una clase oculta a los usuarios","Un trait temporal"], correct:1, explanation:"Útiles para tests rápidos o pasar implementaciones simples de interfaces sin crear un archivo dedicado.", noShuffle:false },
  { concept_id:"dwes_u6_q39", unit:6, question:"¿Qué significa el operador 'Nullsafe' (?->) introducido en PHP 8.0?", options:["Comprueba si un número es positivo, concepto diferente al que se describe en esta pregunta","Permite encadenar llamadas a propiedades o métodos de objetos retornando null inmediatamente si algún elemento intermedio es null, sin lanzar error","Cifra el acceso al objeto, concepto diferente al que se describe en esta pregunta","Comprueba tipos en tiempo de diseño, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"$pais = $usuario?->getDireccion()?->getPais(); evita múltiples comprobaciones anidadas de if ($obj !== null).", noShuffle:false },
  { concept_id:"dwes_u6_q40", unit:6, question:"¿Qué es el patrón 'Observer' en desarrollo de aplicaciones?", options:["Una herramienta de logging, concepto diferente al que se describe en esta pregunta","Un patrón donde un objeto sujeto mantiene una lista de dependientes (observadores) a los que notifica automáticamente ante cambios de estado","Un monitor de CPU, concepto diferente al que se describe en esta pregunta","Un depurador de código, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es la base del sistema de eventos (Events & Listeners) habitual en frameworks como Symfony y Laravel.", noShuffle:false },
  { concept_id:"dwes_u6_q41", unit:6, question:"¿Cuál es la función del comando 'composer install' frente a 'composer update'?", options:["Hacen exactamente lo mismo, concepto diferente al que se describe en esta pregunta","'composer install' instala las versiones exactas fijadas en composer.lock garantizando reproducibilidad; 'composer update' busca las versiones más recientes permitidas en composer.json y actualiza el lock","'composer install' borra la carpeta vendor, concepto diferente al que se describe en esta pregunta","'composer update' solo actualiza PHP, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"En despliegue y producción SIEMPRE se debe usar 'composer install' para garantizar que se ejecutan las mismas dependencias probadas en desarrollo.", noShuffle:false },
  { concept_id:"dwes_u6_q42", unit:6, question:"¿Qué es la arquitectura hexagonal (Ports and Adapters)?", options:["Una web con 6 vistas, concepto diferente al que se describe en esta pregunta","Un patrón de arquitectura de software que aísla la lógica central de negocio de los detalles tecnológicos externos (frameworks, bases de datos, APIs) mediante puertos e interfaces","Un diseño de base de datos con 6 tablas, concepto diferente al que se describe en esta pregunta","Un sistema de enrutamiento hexagonal, que aunque es una herramienta util, no corresponde a esta definicion"], correct:1, explanation:"Permite cambiar la base de datos o el framework web sin modificar una sola línea de la lógica de dominio de negocio.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 7 — Servicios Web y APIs REST
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwes_u7_q1", unit:7, question:"¿Qué significa el acrónimo REST?", options:["Remote Execution Standard Technology","Representational State Transfer","Reliable Ethernet Socket Transmission","Rapid Entity Storage Terminal"], correct:1, explanation:"REST es un estilo de arquitectura de software para sistemas hipermedia distribuidos formulado por Roy Fielding.", noShuffle:false },
  { concept_id:"dwes_u7_q2", unit:7, question:"¿Cuál es el formato de intercambio de datos más utilizado universalmente en APIs REST modernas?", options:["XML, concepto diferente al que se describe en esta pregunta","CSV, concepto diferente al que se describe en esta pregunta","JSON (JavaScript Object Notation)","YAML, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"JSON es el estándar de facto por ser ligero, legible y directamente convertible a tipos nativos en cualquier lenguaje.", noShuffle:false },
  { concept_id:"dwes_u7_q3", unit:7, question:"¿Qué función de PHP convierte un array u objeto a una cadena con formato JSON?", options:["json_decode()","json_encode($datos)","to_json()","serialize_json()"], correct:1, explanation:"json_encode() serializa estructuras de datos de PHP a strings JSON. Admite flags como JSON_UNESCAPED_UNICODE y JSON_PRETTY_PRINT.", noShuffle:false },
  { concept_id:"dwes_u7_q4", unit:7, question:"¿Qué función de PHP convierte una cadena JSON en un objeto o array de PHP?", options:["json_decode($jsonString, $asAssociativeArray)","json_parse(), concepto diferente al que se describe en esta pregunta","unserialize_json(), concepto diferente al que se describe en esta pregunta","from_json(), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"json_decode($json, true) devuelve un array asociativo. Si se pasa false (por defecto), devuelve una instancia de stdClass.", noShuffle:false },
  { concept_id:"dwes_u7_q5", unit:7, question:"¿Cómo se lee el cuerpo (raw body) de una petición HTTP POST/PUT con datos JSON en PHP?", options:["$_POST['json']","file_get_contents('php://input')","$_SERVER['HTTP_BODY']","input_read()"], correct:1, explanation:"$_POST solo procesa formularios form-urlencoded o multipart. Para payloads JSON crudos se debe leer el stream 'php://input'.", noShuffle:false },
  { concept_id:"dwes_u7_q6", unit:7, question:"¿Qué cabecera HTTP debe enviar una API REST en la respuesta para indicar que devuelve JSON?", options:["Content-Type: text/html, concepto diferente al que se describe en esta pregunta","Content-Type: application/json; charset=utf-8","Accept: application/json, concepto diferente al que se describe en esta pregunta","Format: json, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Indica al cliente cómo decodificar el cuerpo de la respuesta.", noShuffle:false },
  { concept_id:"dwes_u7_q7", unit:7, question:"¿Qué verbo HTTP se debe utilizar en una API REST para crear un nuevo recurso?", options:["GET","POST","PUT","PATCH"], correct:1, explanation:"POST se utiliza para crear subordinados en una colección (ej: POST /api/usuarios).", noShuffle:false },
  { concept_id:"dwes_u7_q8", unit:7, question:"¿Qué verbo HTTP se debe utilizar para actualizar de forma completa un recurso existente?", options:["POST","PUT","GET","DELETE"], correct:1, explanation:"PUT se utiliza para sustituir la representación completa del recurso identificado por su ID (ej: PUT /api/usuarios/4).", noShuffle:false },
  { concept_id:"dwes_u7_q9", unit:7, question:"¿Qué verbo HTTP se debe utilizar para aplicar modificaciones parciales a un recurso?", options:["PUT","PATCH","POST","OPTIONS"], correct:1, explanation:"PATCH se usa cuando solo se desea alterar algunos atributos específicos sin enviar toda la entidad.", noShuffle:false },
  { concept_id:"dwes_u7_q10", unit:7, question:"¿Qué verbo HTTP se debe utilizar para eliminar un recurso en una API REST?", options:["REMOVE","DELETE","DESTROY","DROP"], correct:1, explanation:"DELETE solicita la eliminación del recurso especificado en el URI (ej: DELETE /api/articulos/10).", noShuffle:false },
  { concept_id:"dwes_u7_q11", unit:7, question:"¿Qué código de estado HTTP debe devolver una API tras crear exitosamente un nuevo registro?", options:["200 OK","201 Created","204 No Content","202 Accepted"], correct:1, explanation:"201 Created informa de la creación de la entidad, a menudo acompañada de la cabecera Location con el URI del nuevo recurso.", noShuffle:false },
  { concept_id:"dwes_u7_q12", unit:7, question:"¿Qué código de estado HTTP se devuelve habitualmente tras eliminar con éxito un recurso si no hay datos que devolver?", options:["200 OK","204 No Content","404 Not Found","202 Accepted"], correct:1, explanation:"204 No Content confirma que la acción concluyó satisfactoriamente y que el cuerpo de la respuesta está vacío intencionadamente.", noShuffle:false },
  { concept_id:"dwes_u7_q13", unit:7, question:"¿Qué son las siglas JWT en autenticación de APIs?", options:["Java Web Transfer","JSON Web Token","JavaScript Web Template","Joint Wireless Terminal"], correct:1, explanation:"JWT es un estándar abierto (RFC 7519) para transmitir afirmaciones de identidad de forma compacta y firmada digitalmente.", noShuffle:false },
  { concept_id:"dwes_u7_q14", unit:7, question:"¿Cuáles son las tres partes delimitadas por puntos que componen un token JWT?", options:["Usuario, Rol y Permiso, concepto diferente al que se describe en esta pregunta","Header (Cabecera), Payload (Carga útil) y Signature (Firma)","Origen, Destino y Clave, concepto diferente al que se describe en esta pregunta","Host, Path y Query, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Un JWT tiene el formato: xxxxx.yyyyy.zzzzz (Header en Base64Url . Payload en Base64Url . Firma criptográfica).", noShuffle:false },
  { concept_id:"dwes_u7_q15", unit:7, question:"¿Dónde se transporta típicamente un token JWT en las peticiones a una API REST?", options:["En la URL como parámetro ?jwt=..., concepto diferente al que se describe en esta pregunta","En la cabecera HTTP: 'Authorization: Bearer <token>'","En una cookie no cifrada, concepto diferente al que se describe en esta pregunta","En el cuerpo del GET, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La cabecera estándar 'Authorization: Bearer <token>' es el mecanismo universal en arquitecturas desacopladas.", noShuffle:false },
  { concept_id:"dwes_u7_q16", unit:7, question:"¿Por qué NO se debe almacenar información confidencial (como contraseñas) dentro del Payload de un JWT?", options:["Porque el token pesa mucho, concepto diferente al que se describe en esta pregunta","Porque el Payload no está cifrado, solo codificado en Base64Url y cualquiera que intercepte el token puede leerlo inmediatamente","Porque la firma se corrompe, concepto diferente al que se describe en esta pregunta","Porque JSON no admite contraseñas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Un JWT está firmado para garantizar integridad (no ser modificado), pero no está cifrado: sus datos son visibles públicamente.", noShuffle:false },
  { concept_id:"dwes_u7_q17", unit:7, question:"¿Qué claim estándar de un JWT indica la fecha y hora de expiración del token?", options:["exp","iat","sub","nbf"], correct:0, explanation:"'exp' (Expiration Time) contiene un timestamp Unix tras el cual el token debe ser rechazado como inválido.", noShuffle:false },
  { concept_id:"dwes_u7_q18", unit:7, question:"¿Qué es CORS (Cross-Origin Resource Sharing)?", options:["Un tipo de base de datos distribuida, concepto diferente al que se describe en esta pregunta","Un mecanismo de seguridad del navegador que restringe o autoriza a scripts web a realizar peticiones a un dominio distinto al de origen","Un servidor proxy para APIs, concepto diferente al que se describe en esta pregunta","Un protocolo de compresión de vídeo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Por la política del mismo origen (Same-Origin Policy), los navegadores bloquean peticiones fetch/XHR cross-origin a menos que el servidor envíe cabeceras Access-Control-*.", noShuffle:false },
  { concept_id:"dwes_u7_q19", unit:7, question:"¿Qué cabecera de respuesta HTTP en el servidor permite a cualquier cliente acceder a los recursos en CORS?", options:["Access-Control-Allow-Origin: *","Allow-All-Domains: true","Cross-Origin: enable, concepto diferente al que se describe en esta pregunta","Origin: public, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Access-Control-Allow-Origin: * autoriza a cualquier origen externo a leer la respuesta (común en APIs públicas).", noShuffle:false },
  { concept_id:"dwes_u7_q20", unit:7, question:"¿Qué es una petición 'Preflight' en CORS?", options:["Una petición de prueba que envía el usuario manualmente, concepto diferente al que se describe en esta pregunta","Una petición previa automática con método OPTIONS que el navegador emite para comprobar si el servidor autoriza el método y las cabeceras personalizadas","Una descarga previa del HTML, concepto diferente al que se describe en esta pregunta","Un ping de latencia de red, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El navegador envía automáticamente OPTIONS antes de peticiones con métodos PUT, DELETE o cabeceras como Authorization.", noShuffle:false },
  { concept_id:"dwes_u7_q21", unit:7, question:"¿Qué principio REST indica que las interacciones deben incluir enlaces a acciones relacionadas (HATEOAS)?", options:["Statelessness, concepto diferente al que se describe en esta pregunta","Cacheability, concepto diferente al que se describe en esta pregunta","Hypermedia as the Engine of Application State (HATEOAS)","Layered System, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"HATEOAS permite que las respuestas JSON incluyan enlaces (_links) a operaciones posibles (ej: link a pagar factura, cancelar, etc.).", noShuffle:false },
  { concept_id:"dwes_u7_q22", unit:7, question:"¿Cómo se establece el código de respuesta HTTP dinámicamente en PHP?", options:["response_code(404);","http_response_code(404);","set_status(404);","$_SERVER['STATUS'] = 404;"], correct:1, explanation:"http_response_code(404); establece o consulta el código de estado HTTP de la respuesta actual.", noShuffle:false },
  { concept_id:"dwes_u7_q23", unit:7, question:"¿Qué extensión de PHP se utiliza habitualmente para consumir APIs REST externas realizando peticiones HTTP?", options:["cURL","sockets","stream_filter","http_client_raw"], correct:0, explanation:"cURL (curl_init, curl_setopt, curl_exec) permite configurar headers, métodos, proxies y timeouts para consumir servicios remotos.", noShuffle:false },
  { concept_id:"dwes_u7_q24", unit:7, question:"¿Qué librería moderna de PHP basada en PSR-7 es la más utilizada para realizar peticiones HTTP como cliente?", options:["GuzzleHTTP","Axios","RequestsLite","CurlWrapper"], correct:0, explanation:"Guzzle es el cliente HTTP estándar en PHP para consumir APIs con soporte síncrono, asíncrono y promesas.", noShuffle:false },
  { concept_id:"dwes_u7_q25", unit:7, question:"¿Qué es SOAP y en qué se diferencia de REST?", options:["SOAP es más moderno que REST, concepto diferente al que se describe en esta pregunta","SOAP es un protocolo estricto basado obligatoriamente en XML con contrato formal WSDL; REST es un estilo arquitectural más flexible sobre HTTP habitualmente con JSON","SOAP solo funciona en navegadores, concepto diferente al que se describe en esta pregunta","REST solo admite números enteros, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"SOAP tiene una sobrecarga de XML mucho mayor pero incluye estándares de seguridad empresarial (WS-Security).", noShuffle:false },
  { concept_id:"dwes_u7_q26", unit:7, question:"¿Qué es OpenAPI (anteriormente Swagger)?", options:["Un lenguaje de programación de backend, concepto diferente al que se describe en esta pregunta","Una especificación estándar neutral para describir, documentar y consumir APIs RESTful en formato JSON o YAML","Un compilador de PHP, concepto diferente al que se describe en esta pregunta","Un plugin de bases de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"OpenAPI permite generar interfaces interactivas de prueba (Swagger UI) y clientes de código a partir del contrato de la API.", noShuffle:false },
  { concept_id:"dwes_u7_q27", unit:7, question:"¿Qué diferencia hay entre autenticación y autorización en una API?", options:["Son sinónimos perfectos, concepto diferente al que se describe en esta pregunta","Autenticación valida QUIÉN es el usuario (identidad); Autorización comprueba QUÉ puede hacer ese usuario (permisos/roles)","Autorización ocurre antes que la autenticación, concepto diferente al que se describe en esta pregunta","Autenticación es para máquinas y autorización para personas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Primero se autentica la identidad (ej: con token JWT) y luego se autoriza si su rol tiene permiso para ese endpoint.", noShuffle:false },
  { concept_id:"dwes_u7_q28", unit:7, question:"¿Qué es GraphQL frente a una API REST tradicional?", options:["Un sistema operativo, que aunque es una herramienta util, no corresponde a esta definicion","Un lenguaje de consulta para APIs donde el cliente especifica exactamente qué campos necesita recibir en una sola petición, evitando sobrecarga de datos (over-fetching)","Un framework de CSS, concepto diferente al que se describe en esta pregunta","Un servidor web, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"GraphQL ofrece un único endpoint tipado (/graphql) y evita tener que crear múltiples endpoints REST especializados.", noShuffle:false },
  { concept_id:"dwes_u7_q29", unit:7, question:"¿Qué significa el problema 'Under-fetching' en APIs REST?", options:["Que la API devuelve demasiados campos innecesarios, concepto diferente al que se describe en esta pregunta","Que una petición no devuelve suficientes datos, obligando al cliente a realizar múltiples peticiones secuenciales adicionales a otros endpoints","Que la base de datos se queda sin memoria, concepto diferente al que se describe en esta pregunta","Que la conexión se cierra antes de tiempo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Ocurre cuando para pintar una pantalla se debe llamar a /usuarios/1, luego a /usuarios/1/pedidos y luego a /pedidos/10/lineas.", noShuffle:false },
  { concept_id:"dwes_u7_q30", unit:7, question:"¿Qué patrón de paginación es más eficiente para grandes volúmenes de datos en APIs REST?", options:["Offset Paging (LIMIT 10 OFFSET 1000000)","Cursor-based Paging (Seek Paging: WHERE id > last_seen_id LIMIT 10)","Descargar todos los registros y paginar en el cliente","Paginación aleatoria"], correct:1, explanation:"La paginación basada en cursor aprovecha índices de BD directamente sin tener que escanear y descartar millones de filas intermedias.", noShuffle:false },
  { concept_id:"dwes_u7_q31", unit:7, question:"¿Cómo se implementa el versionado de una API REST de forma estándar?", options:["Cambiando el nombre de las columnas en BD, concepto diferente al que se describe en esta pregunta","En la URL (ej: /api/v1/productos) o mediante cabeceras HTTP personalizadas (ej: Accept: application/vnd.app.v1+json)","Reiniciando el servidor, concepto diferente al que se describe en esta pregunta","No se deben versionar las APIs, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El versionado en URL (/v1/, /v2/) es el más visible y popular para no romper compatibilidad con clientes existentes.", noShuffle:false },
  { concept_id:"dwes_u7_q32", unit:7, question:"¿Qué código de error debe devolver json_last_error() en PHP si la decodificación fue correcta?", options:["JSON_ERROR_NONE","0, concepto diferente al que se describe en esta pregunta","JSON_OK, concepto diferente al que se describe en esta pregunta","true, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"JSON_ERROR_NONE (valor 0) confirma que la cadena JSON no tuvo problemas de sintaxis o profundidad excesiva.", noShuffle:false },
  { concept_id:"dwes_u7_q33", unit:7, question:"¿Qué flag de json_decode() introducido en PHP 7.3 hace que lance excepciones (JsonException) automáticamente en caso de error?", options:["JSON_THROW_ON_ERROR","JSON_STRICT","JSON_ERROR_EXCEPTION","JSON_CATCH"], correct:0, explanation:"json_decode($json, true, 512, JSON_THROW_ON_ERROR) evita tener que consultar json_last_error() manualmente.", noShuffle:false },
  { concept_id:"dwes_u7_q34", unit:7, question:"¿Qué es un Webhook en la comunicación entre aplicaciones web?", options:["Un virus espía, concepto diferente al que se describe en esta pregunta","Un mecanismo de comunicación inversa donde el servidor emite una notificación HTTP POST automática a una URL del cliente ante un evento ocurrido (event-driven)","Un socket TCP persistente, concepto diferente al que se describe en esta pregunta","Un formulario HTML, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Servicios como Stripe o GitHub usan Webhooks para avisar a tu backend inmediatamente tras un pago o un commit.", noShuffle:false },
  { concept_id:"dwes_u7_q35", unit:7, question:"¿Cómo se valida la autenticidad de un Webhook recibido?", options:["Comprobando si el JSON es válido, concepto diferente al que se describe en esta pregunta","Verificando una firma HMAC enviada en una cabecera (usando una clave secreta compartida) contra el contenido crudo del cuerpo","No se puede validar, concepto diferente al que se describe en esta pregunta","Verificando que el método sea GET, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"hash_hmac('sha256', $rawBody, $secret) asegura que el payload no fue alterado y proviene del proveedor legítimo.", noShuffle:false },
  { concept_id:"dwes_u7_q36", unit:7, question:"¿Qué es OAuth 2.0?", options:["Un algoritmo de cifrado simétrico, concepto diferente al que se describe en esta pregunta","Un protocolo y marco de autorización que permite a aplicaciones de terceros obtener acceso limitado a recursos de usuario sin conocer sus contraseñas","Un tipo de base de datos, concepto diferente al que se describe en esta pregunta","Un estándar de CSS, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite escenarios como 'Iniciar sesión con Google' o conceder a una app permiso para leer tu calendario.", noShuffle:false },
  { concept_id:"dwes_u7_q37", unit:7, question:"¿Qué papel juega el 'Refresh Token' en autenticación JWT?", options:["Refrescar la caché del navegador, concepto diferente al que se describe en esta pregunta","Un token de larga duración utilizado para solicitar un nuevo Access Token de corta duración cuando este último expira, sin pedir credenciales al usuario","Borrar las sesiones, concepto diferente al que se describe en esta pregunta","Comprobar la conexión a internet, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los Access Tokens duran poco (ej: 15 min) por seguridad; el Refresh Token permite renovarlos de forma controlada y revocable.", noShuffle:false },
  { concept_id:"dwes_u7_q38", unit:7, question:"¿Qué interfaz estándar de PHP (PSR) define las interfaces para mensajes HTTP (Request y Response)?", options:["PSR-3","PSR-7","PSR-11","PSR-15"], correct:1, explanation:"PSR-7 define representaciones inmutables de peticiones y respuestas HTTP estándar para el ecosistema PHP.", noShuffle:false },
  { concept_id:"dwes_u7_q39", unit:7, question:"¿Qué es SSE (Server-Sent Events) frente a WebSockets?", options:["SSE es bidireccional y WebSockets unidireccional, concepto diferente al que se describe en esta pregunta","SSE permite al servidor enviar flujos continuos de eventos en tiempo real al cliente sobre HTTP estándar de forma unidireccional; WebSockets es bidireccional sobre TCP","SSE requiere Flash, concepto diferente al que se describe en esta pregunta","Son idénticos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"SSE (Content-Type: text/event-stream) es ideal para notificaciones o cotizaciones donde solo el servidor envía datos continuamente.", noShuffle:false },
  { concept_id:"dwes_u7_q40", unit:7, question:"¿Qué cabecera HTTP informa al cliente cuántas peticiones le quedan antes de ser bloqueado por Rate Limiting?", options:["X-RateLimit-Remaining","X-Limit-Status","Rate-Limit-Allowed","X-Requests-Left"], correct:0, explanation:"Cabeceras como X-RateLimit-Limit, X-RateLimit-Remaining y X-RateLimit-Reset coordinan el consumo responsable de la API.", noShuffle:false },
  { concept_id:"dwes_u7_q41", unit:7, question:"¿Qué significa que un recurso REST sea representativo y no procedural?", options:["Que los URIs deben usar nombres/sustantivos en lugar de verbos/acciones","Que debe representarse con dibujos, concepto diferente al que se describe en esta pregunta","Que no puede usar parámetros, concepto diferente al que se describe en esta pregunta","Que requiere base de datos relacional, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Los URIs identifican recursos (sustantivos en plural) y los verbos HTTP (GET, POST, PUT, DELETE) indican la operación.", noShuffle:false },
  { concept_id:"dwes_u7_q42", unit:7, question:"¿Cuál es la función del método HTTP HEAD en una API REST?", options:["Obtener solo las primeras 10 filas, concepto diferente al que se describe en esta pregunta","Idéntico al método GET pero solicitando al servidor que NO retorne el cuerpo (body) en la respuesta, solo las cabeceras","Crear cabeceras en el servidor, concepto diferente al que se describe en esta pregunta","Reiniciar el servidor, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"HEAD permite verificar si un recurso existe, su tamaño (Content-Length) o si ha sido modificado sin gastar ancho de banda descargándolo.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 8 — Seguridad en Aplicaciones Web
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwes_u8_q1", unit:8, question:"¿Qué es el OWASP Top 10?", options:["Los diez lenguajes de programación más rápidos, concepto diferente al que se describe en esta pregunta","Un documento de consenso internacional que lista los diez riesgos de seguridad más críticos en aplicaciones web","Un top de servidores de bases de datos, concepto diferente al que se describe en esta pregunta","Una lista de antivirus para servidores, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"OWASP (Open Web Application Security Project) publica periódicamente los riesgos de seguridad más graves del sector.", noShuffle:false },
  { concept_id:"dwes_u8_q2", unit:8, question:"¿Qué es el ataque de Inyección SQL (SQLi)?", options:["Descargar una base de datos entera por FTP, concepto diferente al que se describe en esta pregunta","Infiltración de comandos SQL maliciosos a través de entradas no saneadas del usuario para alterar las consultas que ejecuta el motor de BD","Un virus que borra discos duros, concepto diferente al que se describe en esta pregunta","Un ataque de saturación de red, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Ocurre cuando datos no confiables se concatenan directamente a una sentencia SQL. Se previene con consultas preparadas.", noShuffle:false },
  { concept_id:"dwes_u8_q3", unit:8, question:"¿Qué es XSS (Cross-Site Scripting)?", options:["Un error en las hojas de estilo CSS, concepto diferente al que se describe en esta pregunta","Una vulnerabilidad que permite a un atacante inyectar scripts maliciosos (generalmente JavaScript) en páginas vistas por otros usuarios","Un fallo en la tarjeta de red, concepto diferente al que se describe en esta pregunta","Robar una base de datos mediante fuerza bruta, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"XSS permite robar cookies, secuestrar sesiones o redirigir usuarios a webs fraudulentas ejecutando JS en su propio navegador.", noShuffle:false },
  { concept_id:"dwes_u8_q4", unit:8, question:"¿Cuál es la diferencia entre XSS Almacenado (Stored) y XSS Reflejado (Reflected)?", options:["No hay diferencia, aunque algunos enfoques establecen matices al respecto","En el Stored el payload malicioso se guarda persistentemente en la BD y se refleja en la respuesta inmediata","Reflected es más peligroso siempre, concepto diferente al que se describe en esta pregunta","Stored solo funciona en servidores Windows, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Stored XSS es devastador porque afecta a todos los usuarios legítimos que carguen la página infectada almacenada en el servidor.", noShuffle:false },
  { concept_id:"dwes_u8_q5", unit:8, question:"¿Qué función de PHP se debe usar obligatoriamente al imprimir datos de usuario en HTML para prevenir XSS?", options:["strip_tags(), concepto diferente al que se describe en esta pregunta","htmlspecialchars($cadena, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8')","addslashes(), concepto diferente al que se describe en esta pregunta","urlencode(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"htmlspecialchars convierte caracteres peligrosos (<, >, &, \", ') en sus correspondientes entidades HTML (&lt;, &gt;...), neutralizando scripts.", noShuffle:false },
  { concept_id:"dwes_u8_q6", unit:8, question:"¿Por qué strip_tags() NO es suficiente por sí sola para prevenir XSS?", options:["Porque es una función lenta, concepto diferente al que se describe en esta pregunta","Porque no previene inyecciones dentro de atributos HTML (como onclick","Porque borra todos los números, concepto diferente al que se describe en esta pregunta","Porque solo funciona en PHP 5, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"strip_tags elimina tags pero puede dejar atributos peligrosos o fallar con strings truncados. El escapado contextual es la regla.", noShuffle:false },
  { concept_id:"dwes_u8_q7", unit:8, question:"¿Qué función de PHP se utiliza para validar y sanear tipos de datos nativos como emails o URLs?", options:["filter_var($email, FILTER_VALIDATE_EMAIL)","check_email(), concepto diferente al que se describe en esta pregunta","preg_replace() exclusivamente","validate_data(), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"filter_var() proporciona filtros estandarizados y auditados para emails, IPs, URLs, enteros, booleanos, etc.", noShuffle:false },
  { concept_id:"dwes_u8_q8", unit:8, question:"¿Qué es una inyección de comandos del sistema operativo (Command Injection)?", options:["Escribir mal un comando en la consola, concepto diferente al que se describe en esta pregunta","Cuando una aplicación pasa entradas del usuario sin sanear a funciones de ejecución del sistema como exec(), system() o shell_exec()","Un virus que sobrecalienta el procesador, concepto diferente al que se describe en esta pregunta","Un fallo en la memoria RAM, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite a un atacante ejecutar comandos arbitrarios de Linux/Windows con los privilegios del servidor web (ej: concatenar '; rm -rf /').", noShuffle:false },
  { concept_id:"dwes_u8_q9", unit:8, question:"¿Qué función de PHP escapa argumentos antes de pasarlos a comandos de shell del sistema?", options:["addslashes(), concepto diferente al que se describe en esta pregunta","escapeshellarg() y escapeshellcmd()","htmlspecialchars(), concepto diferente al que se describe en esta pregunta","strip_tags(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"escapeshellarg() rodea el argumento de comillas simples y escapa comillas existentes para que sea interpretado como un único parámetro literal.", noShuffle:false },
  { concept_id:"dwes_u8_q10", unit:8, question:"¿Qué es el ataque de Path Traversal (Directory Traversal)?", options:["Navegar por las páginas de una web, concepto diferente al que se describe en esta pregunta","Explotar rutas de archivos usando secuencias '../' en entradas del usuario para acceder a archivos fuera del directorio web","Un ataque contra los routers de internet, concepto diferente al que se describe en esta pregunta","Un rastreador de Google, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite descargar código fuente, archivos de configuración o ficheros del sistema no expuestos públicamente.", noShuffle:false },
  { concept_id:"dwes_u8_q11", unit:8, question:"¿Qué función de PHP devuelve la ruta absoluta canónica resolviendo enlaces y referencias '../'?", options:["realpath($ruta)","pathinfo()","basename()","canon_path()"], correct:0, explanation:"realpath() expande symlinks y referencias ../. Permite verificar que la ruta final comience estrictamente por la carpeta autorizada.", noShuffle:false },
  { concept_id:"dwes_u8_q12", unit:8, question:"¿Qué riesgo crítico presenta permitir la subida de archivos (File Upload) sin validación estricta?", options:["Que se llene el disco duro únicamente, concepto diferente al que se describe en esta pregunta","Que un atacante suba un script PHP malicioso (Webshell) al directorio público y lo ejecute navegando a su URL, tomando el control total del servidor","Que el archivo cambie de formato, concepto diferente al que se describe en esta pregunta","Que el nombre sea muy largo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Subir un archivo .php permite Ejecución Remota de Código (RCE). Se debe validar extensión, MIME real y almacenar fuera de la raíz web.", noShuffle:false },
  { concept_id:"dwes_u8_q13", unit:8, question:"¿Por qué validar únicamente $_FILES['archivo']['type'] no es seguro al subir archivos?", options:["Porque es lento, concepto diferente al que se describe en esta pregunta","Porque esa cabecera es enviada por el cliente y el atacante puede manipularla libremente para enviar un archivo PHP diciendo que es image/jpeg","Porque solo funciona en imágenes, concepto diferente al que se describe en esta pregunta","Porque devuelve cadenas vacías, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El MIME del cliente no es confiable. Se debe inspeccionar el contenido real en el servidor con la extensión Fileinfo (finfo_file()).", noShuffle:false },
  { concept_id:"dwes_u8_q14", unit:8, question:"¿Qué es Content Security Policy (CSP)?", options:["Una ley de protección de datos, concepto diferente al que se describe en esta pregunta","Una cabecera HTTP de seguridad que indica al navegador qué fuentes de scripts, estilos, imágenes y conexiones externas están autorizadas a cargarse","Un plugin de WordPress, concepto diferente al que se describe en esta pregunta","Un cortafuegos físico, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"CSP restringe drásticamente la ejecución de scripts no autorizados, convirtiéndose en la defensa más potente contra XSS.", noShuffle:false },
  { concept_id:"dwes_u8_q15", unit:8, question:"¿Qué es un ataque DoS/DDoS (Denegación de Servicio)?", options:["Robar la contraseña de root, concepto diferente al que se describe en esta pregunta","Sobrecargar intencionadamente un servidor con un aluvión masivo de tráfico o peticiones complejas para dejarlo inoperativo e inaccesible a usuarios legítimos","Modificar la página principal (Defacement), concepto diferente al que se describe en esta pregunta","Borrar registros de una tabla, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los ataques DDoS emplean botnets distribuidas para saturar el ancho de banda o agotar la CPU del servidor web.", noShuffle:false },
  { concept_id:"dwes_u8_q16", unit:8, question:"¿Qué peligro tiene la función unserialize() de PHP con datos suministrados por el usuario?", options:["Que tarda mucho en procesar, concepto diferente al que se describe en esta pregunta","Inyección de Objetos PHP (PHP Object Injection): puede desencadenar la ejecución de métodos mágicos (__destruct, __wakeup) llevando a RCE","Que corrompe el charset, concepto diferente al que se describe en esta pregunta","Ninguno, es totalmente segura, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Nunca se debe usar unserialize() sobre datos no confiables. Se debe emplear siempre json_decode().", noShuffle:false },
  { concept_id:"dwes_u8_q17", unit:8, question:"¿Qué es el ataque de fijación de sesión (Session Fixation)?", options:["Impedir que el usuario cierre sesión, concepto diferente al que se describe en esta pregunta","Un atacante induce a la víctima a autenticarse usando un identificador de sesión fijado previamente por el propio atacante para compartir la sesión","Bloquear el navegador, concepto diferente al que se describe en esta pregunta","Acelerar la expiración de cookies, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Se neutraliza invocando session_regenerate_id(true) inmediatamente tras validar las credenciales de login.", noShuffle:false },
  { concept_id:"dwes_u8_q18", unit:8, question:"¿Qué cabecera HTTP protege contra ataques de confusión de tipo MIME (MIME-sniffing)?", options:["X-Content-Type-Options: nosniff","X-Frame-Options: DENY, concepto diferente al que se describe en esta pregunta","X-XSS-Protection: 1, concepto diferente al que se describe en esta pregunta","Content-Encoding: gzip"], correct:0, explanation:"'nosniff' impide que el navegador intente adivinar el contenido e interprete un archivo de texto o imagen subido como ejecutable JavaScript.", noShuffle:false },
  { concept_id:"dwes_u8_q19", unit:8, question:"¿Qué es un ataque Man-in-the-Middle (MitM)?", options:["Un programador trabajando en dos ordenadores, concepto diferente al que se describe en esta pregunta","Un atacante intercepta o altera la comunicación de red entre el cliente y el servidor sin que ninguna de las dos partes lo note","Un intermediario de bases de datos, concepto diferente al que se describe en esta pregunta","Un proxy de caché, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El uso estricto de HTTPS con certificados válidos y HSTS previene la lectura o alteración de tráfico en tránsito.", noShuffle:false },
  { concept_id:"dwes_u8_q20", unit:8, question:"¿Por qué nunca se deben almacenar secretos o credenciales de base de datos en el repositorio de control de versiones (Git)?", options:["Porque Git no admite contraseñas, concepto diferente al que se describe en esta pregunta","Porque cualquier persona con acceso al repositorio (o si este se vuelve público por error) obtendrá acceso directo a los sistemas productivos","Porque hace que los commits pesen más, concepto diferente al que se describe en esta pregunta","Porque rompe las ramas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las credenciales deben almacenarse en archivos de variables de entorno (.env) incluidos en el archivo .gitignore.", noShuffle:false },
  { concept_id:"dwes_u8_q21", unit:8, question:"¿Qué es el principio de Privilegio Mínimo (Least Privilege) en la configuración de la base de datos?", options:["Dar permisos de administrador a todos los usuarios, concepto diferente al que se describe en esta pregunta","Asignar al usuario de la BD utilizado por la aplicación web únicamente los permisos estrictamente necesarios","No poner contraseña al usuario, concepto diferente al que se describe en esta pregunta","Tener solo una tabla, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si la aplicación sufre una inyección SQL, los privilegios restringidos impiden acciones destructivas mayores como eliminar esquemas completos.", noShuffle:false },
  { concept_id:"dwes_u8_q22", unit:8, question:"¿Qué ataque aprovecha vulnerabilidades en analizadores de documentos XML para leer archivos locales del servidor?", options:["XXE (XML External Entity Injection)","XSS, concepto diferente al que se describe en esta pregunta","SQLi, concepto diferente al que se describe en esta pregunta","CSRF, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"XXE explota referencias a entidades externas en el DTD XML para extraer archivos del sistema como /etc/passwd.", noShuffle:false },
  { concept_id:"dwes_u8_q23", unit:8, question:"¿Qué función de PHP desactiva la carga de entidades externas XML para mitigar ataques XXE?", options:["libxml_disable_entity_loader(true)","xml_disable_external(), concepto diferente al que se describe en esta pregunta","xml_secure_mode(true), concepto diferente al que se describe en esta pregunta","disable_xxe(), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"libxml_disable_entity_loader(true) o el uso de flags seguros en DOMDocument previene el procesamiento de entidades maliciosas.", noShuffle:false },
  { concept_id:"dwes_u8_q24", unit:8, question:"¿Qué es el 'Clickjacking'?", options:["Hacer clic muy rápido en un botón es una accion que no define correctamente este concepto","Engañar a un usuario para que haga clic en un elemento invisible colocado estratégicamente sobre una página legítima cargada dentro de un iframe transparente","Descargar virus al pulsar enlaces, concepto diferente al que se describe en esta pregunta","Un error del ratón, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Se mitiga enviando la cabecera 'X-Frame-Options: SAMEORIGIN' o CSP con la directiva frame-ancestors.", noShuffle:false },
  { concept_id:"dwes_u8_q25", unit:8, question:"¿Qué es un ataque de fuerza bruta contra un formulario de autenticación?", options:["Romper el teclado del ordenador, concepto diferente al que se describe en esta pregunta","Probar automáticamente miles o millones de combinaciones de usuarios y contraseñas hasta encontrar una correcta","Inyectar código SQL en los campos, concepto diferente al que se describe en esta pregunta","Saturar la red con paquetes UDP, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Se previene implementando límites de intentos (Rate Limiting), bloqueos progresivos, CAPTCHA y autenticación multifactor.", noShuffle:false },
  { concept_id:"dwes_u8_q26", unit:8, question:"¿Qué es CAPTCHA y para qué se emplea?", options:["Un gestor de descargas, concepto diferente al que se describe en esta pregunta","Una prueba de Turing pública y automatizada para diferenciar humanos de robots o scripts automatizados","Un tipo de base de datos, concepto diferente al que se describe en esta pregunta","Un método de cifrado de disco, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"CAPTCHA (ej: Cloudflare Turnstile o Google reCAPTCHA) detiene bots de spam, fuerza bruta y scraping masivo.", noShuffle:false },
  { concept_id:"dwes_u8_q27", unit:8, question:"¿Qué es SSRF (Server-Side Request Forgery)?", options:["Modificar peticiones en el cliente, concepto diferente al que se describe en esta pregunta","Una vulnerabilidad donde un servidor web es inducido por el atacante a realizar peticiones HTTP hacia servicios internos de su propia red privada","Un ataque contra el protocolo SSH, concepto diferente al que se describe en esta pregunta","Inyección de código en JavaScript, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"SSRF permite a un atacante acceder a servicios no expuestos a internet (ej: instancias internas de Redis, bases de datos o metadatos de AWS).", noShuffle:false },
  { concept_id:"dwes_u8_q28", unit:8, question:"¿Cómo se mitiga el ataque de Enumeración de Usuarios en un formulario de login o recuperación de contraseña?", options:["Mostrando si el email existe o no, concepto diferente al que se describe en esta pregunta","Devolviendo siempre un mensaje idéntico y neutro tanto si el usuario existe como si no","Bloqueando el formulario, concepto diferente al que se describe en esta pregunta","Enviando contraseñas por correo en texto plano, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Mensajes diferenciados como 'Usuario no encontrado' frente a 'Contraseña incorrecta' permiten al atacante confeccionar listas de usuarios reales.", noShuffle:false },
  { concept_id:"dwes_u8_q29", unit:8, question:"¿Qué peligro tiene la inclusión dinámica de archivos como include($_GET['pagina'] . '.php')?", options:["LFI (Local File Inclusion) y RFI (Remote File Inclusion): el atacante puede forzar la inclusión y ejecución de archivos arbitrarios del servidor o de URLs remotas","Que la página se carga más lenta, concepto diferente al que se describe en esta pregunta","Que no se aplican los estilos CSS, concepto diferente al que se describe en esta pregunta","Que la base de datos se bloquea, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Permite incluir archivos como /etc/passwd o cargar scripts remotos si allow_url_include está habilitado.", noShuffle:false },
  { concept_id:"dwes_u8_q30", unit:8, question:"¿Cómo se debe proteger la inclusión dinámica de vistas o plantillas en PHP?", options:["Permitiendo cualquier entrada de usuario, concepto diferente al que se describe en esta pregunta","Usando una lista blanca (whitelist) estricta de páginas autorizadas: in_array($pag, $permitidas)","Usando strip_tags, concepto diferente al que se describe en esta pregunta","Con comillas simples, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El enfoque de lista blanca (whitelist) rechaza cualquier valor que no esté explícitamente enumerado de antemano.", noShuffle:false },
  { concept_id:"dwes_u8_q31", unit:8, question:"¿Qué es el 'Mass Assignment' (Asignación Masiva) en frameworks con ORM?", options:["Asignar tareas a múltiples programadores, concepto diferente al que se describe en esta pregunta","Cuando un atacante envía parámetros adicionales inesperados en una petición HTTP (ej","Un error en las migraciones, concepto diferente al que se describe en esta pregunta","Cargar muchos archivos a la vez, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Se previene definiendo propiedades protegidas o listas blancas de atributos rellenables ($fillable en Laravel).", noShuffle:false },
  { concept_id:"dwes_u8_q32", unit:8, question:"¿Qué es el 'IDOR' (Insecure Direct Object References)?", options:["Un tipo de clave primaria, concepto diferente al que se describe en esta pregunta","Cuando una aplicación expone referencias directas a objetos de la BD sin validar si el usuario autenticado tiene permiso real para acceder a esa entidad concreta","Un error de sintaxis en PHP, concepto diferente al que se describe en esta pregunta","Una clave duplicada, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite a un usuario consultar o modificar datos de otros clientes simplemente alterando el número identificador en la URL.", noShuffle:false },
  { concept_id:"dwes_u8_q33", unit:8, question:"¿Por qué se deben mantener las dependencias de Composer y extensiones de PHP actualizadas periódicamente?", options:["Para cambiar el aspecto visual, concepto diferente al que se describe en esta pregunta","Para corregir vulnerabilidades de seguridad conocidas y publicadas (CVEs) en librerías de terceros","Porque el código antiguo se borra solo, concepto diferente al que se describe en esta pregunta","Para reducir el tamaño de las fuentes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Herramientas como 'composer audit' analizan dependencias en busca de paquetes con fallos de seguridad documentados.", noShuffle:false },
  { concept_id:"dwes_u8_q34", unit:8, question:"¿Qué directiva de php.ini prohíbe que include o require abran URLs remotas?", options:["allow_url_include = Off","allow_url_fopen = Off","remote_include = 0","disable_remote = 1"], correct:0, explanation:"allow_url_include = Off (desactivado por defecto) neutraliza los ataques de Remote File Inclusion (RFI).", noShuffle:false },
  { concept_id:"dwes_u8_q35", unit:8, question:"¿Qué directiva de php.ini permite deshabilitar funciones potencialmente peligrosas para la ejecución de comandos?", options:["disable_functions = exec,system,shell_exec,passthru,proc_open","safe_mode = On, concepto diferente al que se describe en esta pregunta","block_commands = 1, concepto diferente al que se describe en esta pregunta","no_shell = true, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"disable_functions bloquea el acceso a funciones críticas del sistema operativo en entornos compartidos o restringidos.", noShuffle:false },
  { concept_id:"dwes_u8_q36", unit:8, question:"¿Qué permiso numérico octal en sistemas Linux es el recomendado para archivos PHP en un servidor web?", options:["777 (Lectura, escritura y ejecución para todos), concepto diferente al que se describe en esta pregunta","644 (Lectura y escritura para el dueño, solo lectura para los demás)","000, concepto diferente al que se describe en esta pregunta","755, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"644 para archivos y 755 para directorios garantiza que otros usuarios del sistema no puedan sobreescribir código PHP ejecutable.", noShuffle:false },
  { concept_id:"dwes_u8_q37", unit:8, question:"¿Por qué NUNCA se debe dar permisos 777 a una carpeta pública en un servidor de producción?", options:["Porque gasta más CPU, concepto diferente al que se describe en esta pregunta","Porque otorga permisos de escritura y ejecución a absolutamente cualquier usuario o proceso del sistema","Porque rompe el servidor Apache, concepto diferente al que se describe en esta pregunta","Porque no permite guardar imágenes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"777 en directorios accesibles desde la web es una de las causas más frecuentes de intrusión y desfiguración de sitios web.", noShuffle:false },
  { concept_id:"dwes_u8_q38", unit:8, question:"¿Qué función cumple la cabecera 'Referrer-Policy' en seguridad web?", options:["Controlar qué información de la URL de origen se envía en la cabecera Referer al navegar a enlaces externos","Evitar que se copien los textos, concepto diferente al que se describe en esta pregunta","Definir las palabras clave para SEO, concepto diferente al que se describe en esta pregunta","Bloquear peticiones POST, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Valores como 'strict-origin-when-cross-origin' impiden la filtración de tokens o parámetros confidenciales presentes en la URL.", noShuffle:false },
  { concept_id:"dwes_u8_q39", unit:8, question:"¿Qué es el 'Security through Obscurity' (Seguridad por Oscuridad) y cuál es su consenso en ingeniería?", options:["La mejor estrategia de seguridad existente, concepto diferente al que se describe en esta pregunta","Una mala práctica que asume falsamente que un sistema es seguro simplemente ocultando sus detalles o usando puertos no estándar; no debe sustituir nunca a controles criptográficos reales","Cifrar el código fuente, concepto diferente al que se describe en esta pregunta","Apagar la pantalla del servidor, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Ocultar nombres o puertos puede frenar escaneos no dirigidos, pero no resiste el análisis de un atacante con conocimientos.", noShuffle:false },
  { concept_id:"dwes_u8_q40", unit:8, question:"¿Qué es un 'Race Condition' (Condición de Carrera) en seguridad de aplicaciones web?", options:["Una competición de velocidad de código, concepto diferente al que se describe en esta pregunta","Un fallo que ocurre cuando dos peticiones concurrentes acceden y modifican el mismo recurso compartido sin bloqueo","Un error en las consultas JOIN, concepto diferente al que se describe en esta pregunta","Un bucle infinito, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Se mitiga mediante bloqueos pesimistas en bases de datos (SELECT ... FOR UPDATE) o transacciones serializables.", noShuffle:false },
  { concept_id:"dwes_u8_q41", unit:8, question:"¿Qué herramienta de logging es el estándar de facto en PHP para registrar eventos y auditorías de seguridad?", options:["Monolog","Syslog exclusivo","Echo","ErrorLogger"], correct:0, explanation:"Monolog (estándar PSR-3) permite enviar logs estructurados con niveles (INFO, WARNING, ALERT) a archivos, bases de datos o servicios como Elasticsearch.", noShuffle:false },
  { concept_id:"dwes_u8_q42", unit:8, question:"¿Qué política de retención de logs es necesaria para el análisis forense tras un incidente de seguridad?", options:["Borrar los logs cada 24 horas, concepto diferente al que se describe en esta pregunta","Almacenar logs inmutables y centralizados en un servidor externo durante un tiempo prudencial respetando normativas de privacidad","No guardar logs para no ocupar espacio, concepto diferente al que se describe en esta pregunta","Guardar solo los logs de éxito, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Tener registros históricos inalterables permite investigar el origen, alcance y vectores utilizados en una brecha de seguridad.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 9 — Despliegue y Entornos de Ejecución
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwes_u9_q1", unit:9, question:"¿Qué diferencia fundamental hay entre un entorno de Desarrollo y uno de Producción en DWES?", options:["Ninguna, son idénticos, concepto diferente al que se describe en esta pregunta","En desarrollo se muestran errores detallados y se usan datos ficticios","En desarrollo no se usa PHP, concepto diferente al que se describe en esta pregunta","En producción no hay bases de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"En producción display_errors debe estar a Off, las cachés de configuración y rutas compiladas, y las credenciales estrictamente restringidas.", noShuffle:false },
  { concept_id:"dwes_u9_q2", unit:9, question:"¿Qué es un contenedor Docker?", options:["Un archivo comprimido ZIP, concepto diferente al que se describe en esta pregunta","Una unidad de software ligera y portable que empaqueta una aplicación con todo su código, dependencias y entorno de ejecución de forma aislada","Una máquina virtual pesada con su propio kernel de SO completo, concepto diferente al que se describe en esta pregunta","Un servidor físico en un datacenter, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"A diferencia de las máquinas virtuales, los contenedores comparten el kernel del host, haciéndolos ligeros y rápidos de iniciar.", noShuffle:false },
  { concept_id:"dwes_u9_q3", unit:9, question:"¿Qué archivo describe cómo construir una imagen personalizada de Docker para una aplicación PHP?", options:["docker-compose.yml","Dockerfile","package.json","php.ini"], correct:1, explanation:"El archivo Dockerfile contiene las instrucciones secuenciales (FROM, RUN, COPY, EXPOSE, CMD) para armar la imagen.", noShuffle:false },
  { concept_id:"dwes_u9_q4", unit:9, question:"¿Qué herramienta permite definir y ejecutar aplicaciones multi-contenedor (ej: PHP-FPM + Nginx + MySQL) con un solo archivo YAML?", options:["Docker Compose","Docker Swarm","Kubernetes CLI","Vagrant"], correct:0, explanation:"docker-compose.yml define los servicios, redes y volúmenes, permitiendo levantar todo el stack con 'docker compose up -d'.", noShuffle:false },
  { concept_id:"dwes_u9_q5", unit:9, question:"¿Para qué se utilizan los 'Volúmenes' en Docker?", options:["Para subir el volumen del audio, concepto diferente al que se describe en esta pregunta","Para persistir datos fuera del ciclo de vida del contenedor y compartirlos con el sistema host","Para acelerar la CPU, concepto diferente al que se describe en esta pregunta","Para balancear la red, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los contenedores son efímeros por naturaleza; sin volúmenes, cualquier dato generado en su interior se pierde al destruir el contenedor.", noShuffle:false },
  { concept_id:"dwes_u9_q6", unit:9, question:"¿Qué librería de PHP permite cargar variables de entorno desde un archivo '.env' en desarrollo?", options:["vlucas/phpdotenv","composer/env","env-loader, concepto diferente al que se describe en esta pregunta","system-env, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"phpdotenv lee el archivo .env y carga los valores en $_ENV y getenv() para no hardcodear credenciales.", noShuffle:false },
  { concept_id:"dwes_u9_q7", unit:9, question:"¿Qué archivo debe subirse a Git como plantilla de variables de entorno sin valores sensibles reales?", options:[".env, concepto diferente al que se describe en esta pregunta",".env.example o .env.dist",".env.local, concepto diferente al que se describe en esta pregunta",".env.production, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:".env.example define las claves requeridas (DB_HOST, DB_PASS...) con valores de muestra sin exponer credenciales productivas reales.", noShuffle:false },
  { concept_id:"dwes_u9_q8", unit:9, question:"¿Qué comando de Composer optimiza el cargador de clases para entornos de producción?", options:["composer install --no-dev --optimize-autoloader","composer update --all, concepto diferente al que se describe en esta pregunta","composer build, concepto diferente al que se describe en esta pregunta","composer fast, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"--optimize-autoloader genera un mapa de clases autoritativo en memoria (classmap) que evita búsquedas en el sistema de archivos.", noShuffle:false },
  { concept_id:"dwes_u9_q9", unit:9, question:"¿Qué es OPcache en PHP?", options:["Un compilador de JavaScript, concepto diferente al que se describe en esta pregunta","Una extensión nativa de PHP que almacena en memoria RAM el código intermedio (bytecode/opcodes) precompilado de los scripts para evitar interpretarlos en cada petición","Un sistema gestor de bases de datos, que aunque es una herramienta util, no corresponde a esta definicion","Un optimizador de imágenes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"OPcache multiplica exponencialmente el rendimiento de PHP al eliminar la sobrecarga de lectura y compilación continua de archivos en disco.", noShuffle:false },
  { concept_id:"dwes_u9_q10", unit:9, question:"¿Qué herramienta de testing es el estándar de facto para realizar pruebas unitarias automatizadas en PHP?", options:["PHPUnit","Jest","Mocha","PyTest"], correct:0, explanation:"PHPUnit permite escribir suites de tests automatizados comprobando aserciones (assertEquals, assertTrue) sobre clases y métodos.", noShuffle:false },
  { concept_id:"dwes_u9_q11", unit:9, question:"¿Qué diferencia a un Test Unitario de un Test de Integración?", options:["El test unitario es más largo, concepto diferente al que se describe en esta pregunta","El test unitario prueba un método o clase aislada aislando sus dependencias mediante dobles de prueba (mocks); el de integración comprueba la interacción real entre varios componentes","Son sinónimos, concepto diferente al que se describe en esta pregunta","Los unitarios solo los ejecuta el cliente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los tests unitarios son rápidos y específicos; los de integración verifican que el ensamblaje global de piezas funciona correctamente.", noShuffle:false },
  { concept_id:"dwes_u9_q12", unit:9, question:"¿Qué es la Integración Continua (CI - Continuous Integration)?", options:["Subir código a internet todos los días, concepto diferente al que se describe en esta pregunta","Una práctica de desarrollo donde los miembros del equipo integran su código frecuentemente en un repositorio compartido y cada integración se valida con tests automatizados","Hacer copias de seguridad continuas es una accion que no define correctamente este concepto","Desplegar en el servidor a mano, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Servicios como GitHub Actions o GitLab CI ejecutan automáticamente linter, pruebas y auditorías en cada pull request.", noShuffle:false },
  { concept_id:"dwes_u9_q13", unit:9, question:"¿Qué es el Despliegue Continuo (CD - Continuous Deployment)?", options:["Escribir código sin parar, concepto diferente al que se describe en esta pregunta","La automatización completa del pipeline donde cada cambio que supera satisfactoriamente todas las pruebas de CI se despliega automáticamente a producción sin intervención manual","Crear ramas infinitas en Git, concepto diferente al que se describe en esta pregunta","Reiniciar el servidor en bucle, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite entregar valor y correcciones a los usuarios finales de forma ágil, fiable y repetible.", noShuffle:false },
  { concept_id:"dwes_u9_q14", unit:9, question:"¿Qué técnica de despliegue se conoce como 'Blue-Green Deployment'?", options:["Pintar los servidores de dos colores, concepto diferente al que se describe en esta pregunta","Mantener dos entornos productivos idénticos (uno activo y otro en espera)","Desplegar de noche únicamente, concepto diferente al que se describe en esta pregunta","Hacer pruebas en local es una accion que no define correctamente este concepto"], correct:1, explanation:"Permite 'Zero-Downtime Deployment' (despliegue sin caída de servicio) y una reversión casi instantánea si surge algún problema.", noShuffle:false },
  { concept_id:"dwes_u9_q15", unit:9, question:"¿Qué es el 'Zero-Downtime Deployment'?", options:["Desplegar cuando no hay internet, concepto diferente al que se describe en esta pregunta","Actualizar la aplicación sin que los usuarios experimenten ninguna interrupción ni errores de servicio durante el proceso de transición","Un servidor que nunca se apaga, concepto diferente al que se describe en esta pregunta","Desplegar en 0 segundos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Se logra mediante enlaces simbólicos atómicos (ej: carpetas releases y current con herramientas como Deployer) o con contenedores balanceados.", noShuffle:false },
  { concept_id:"dwes_u9_q16", unit:9, question:"¿Qué herramienta en PHP está especializada en automatizar despliegues por SSH mediante scripts?", options:["Deployer","Webpack","Composer únicamente","Vagrant"], correct:0, explanation:"Deployer (deployer.org) es una herramienta CLI en PHP para automatizar tareas de despliegue modular con soporte de rollback atómico.", noShuffle:false },
  { concept_id:"dwes_u9_q17", unit:9, question:"¿Por qué el directorio raíz público de un proyecto PHP debe ser la carpeta 'public' y no la raíz del proyecto?", options:["Porque Nginx no entiende otra carpeta, concepto diferente al que se describe en esta pregunta","Para evitar que archivos sensibles como composer.json, archivos .env","Para que carguen los CSS, concepto diferente al que se describe en esta pregunta","Por estética, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si la raíz web es el directorio raíz del proyecto, un atacante puede descargar el archivo .env con todas las contraseñas de la base de datos.", noShuffle:false },
  { concept_id:"dwes_u9_q18", unit:9, question:"¿Qué es un 'Health Check' (Comprobación de Salud) en arquitecturas de despliegue?", options:["Un antivirus del servidor, concepto diferente al que se describe en esta pregunta","Un endpoint ligero que devuelve 200 OK si la aplicación","Un análisis de memoria RAM, concepto diferente al que se describe en esta pregunta","Un chequeo del hardware, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite a Kubernetes o balanceadores AWS descartar instancias no saludables y reemplazarlas automáticamente.", noShuffle:false },
  { concept_id:"dwes_u9_q19", unit:9, question:"¿Qué es un certificado SSL/TLS gratuito y automatizado proporcionado por la autoridad de certificación Let's Encrypt?", options:["Un certificado que dura 10 años, concepto diferente al que se describe en esta pregunta","Un certificado estándar X.509 de dominio validado automáticamente mediante el protocolo ACME con herramientas como Certbot","Un certificado que no encripta, concepto diferente al que se describe en esta pregunta","Un plugin de Chrome, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Let's Encrypt y Certbot revolucionaron la web permitiendo cifrar HTTPS universalmente con renovación automática cada 90 días.", noShuffle:false },
  { concept_id:"dwes_u9_q20", unit:9, question:"¿Qué directiva de Nginx establece el límite máximo de tamaño permitido para subidas de archivos en peticiones POST?", options:["client_max_body_size 20M;","upload_max_filesize 20M; (es de PHP)","post_max_size 20M; (es de PHP)","max_payload 20M;"], correct:0, explanation:"client_max_body_size en Nginx debe ajustarse para que coincida o supere los límites upload_max_filesize y post_max_size de php.ini.", noShuffle:false },
  { concept_id:"dwes_u9_q21", unit:9, question:"¿Qué ocurre si upload_max_filesize en php.ini es 10M pero post_max_size es 2M al subir un archivo de 5M?", options:["El archivo se sube correctamente, concepto diferente al que se describe en esta pregunta","La subida falla silenciosamente o lanza un error porque post_max_size es el límite global de todo el payload POST y debe ser siempre superior o igual","Se divide en dos archivos, concepto diferente al que se describe en esta pregunta","Se comprime automáticamente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Regla fundamental de configuración en php.ini: memory_limit > post_max_size >= upload_max_filesize.", noShuffle:false },
  { concept_id:"dwes_u9_q22", unit:9, question:"¿Qué es un Balanceador de Carga (Load Balancer)?", options:["Un medidor de tráfico, concepto diferente al que se describe en esta pregunta","Un dispositivo o software que distribuye el tráfico de red entrante entre múltiples servidores backend para optimizar el rendimiento y la disponibilidad","Un SAI de alimentación, concepto diferente al que se describe en esta pregunta","Un acelerador de bases de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Evita que un único servidor se sobrecargue y redirige peticiones a servidores sanos si uno falla.", noShuffle:false },
  { concept_id:"dwes_u9_q23", unit:9, question:"¿Qué estrategia de balanceo de carga asigna peticiones consecutivas a los servidores de forma secuencial y cíclica?", options:["Round Robin","Least Connections","IP Hash","Random"], correct:0, explanation:"Round Robin es el algoritmo más simple y extendido para repartir carga uniformemente entre servidores con capacidades similares.", noShuffle:false },
  { concept_id:"dwes_u9_q24", unit:9, question:"¿Cómo se gestiona el envío de correos masivos o tareas pesadas en una aplicación web sin congelar la respuesta al usuario?", options:["Aumentando el timeout de PHP a 1 hora, concepto diferente al que se describe en esta pregunta","Utilizando colas de trabajo asíncronas (Message Queues) con brokers como RabbitMQ, Redis o Amazon SQS y trabajadores en segundo plano (workers)","Haciendo un bucle while largo, concepto diferente al que se describe en esta pregunta","Pidiendo al usuario que no cierre la pestaña, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La petición web encola la tarea en milisegundos y responde al usuario de inmediato; un worker de CLI procesa el trabajo en segundo plano.", noShuffle:false },
  { concept_id:"dwes_u9_q25", unit:9, question:"¿Qué herramienta de gestión de procesos en Linux mantiene los workers de colas de PHP siempre vivos y los reinicia si se caen?", options:["Supervisor (supervisord) o Systemd","Cron únicamente, concepto diferente al que se describe en esta pregunta","Apache, concepto diferente al que se describe en esta pregunta","Composer, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Supervisor monitoriza procesos de larga duración en segundo plano (como 'php artisan queue:work') reiniciándolos automáticamente ante fallos.", noShuffle:false },
  { concept_id:"dwes_u9_q26", unit:9, question:"¿Cómo se programan tareas periódicas recurrentes en un servidor Linux (ej: generar reportes a medianoche)?", options:["Con un bucle while infinito en PHP","Con el servicio Crontab del sistema operativo","Con setTimeout en el navegador, concepto diferente al que se describe en esta pregunta","Dejando una pestaña abierta, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Crontab programa ejecuciones de comandos según un formato estándar de 5 campos temporales (minuto, hora, día, mes, día de semana).", noShuffle:false },
  { concept_id:"dwes_u9_q27", unit:9, question:"¿Qué es el patrón de ejecución de tareas programadas 'Task Scheduling' que implementan frameworks como Laravel o Symfony?", options:["Pedir a los usuarios que programen alarmas es una accion que no define correctamente este concepto","Configurar una única entrada en Crontab que llama al framework cada minuto ('* * * * * php artisan schedule:run'), delegando la lógica de programación al código PHP","Un calendario en la base de datos, concepto diferente al que se describe en esta pregunta","Un cron para cada función, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Centraliza toda la planificación de tareas en el código versionado con Git sin necesidad de manipular manualmente el crontab del servidor.", noShuffle:false },
  { concept_id:"dwes_u9_q28", unit:9, question:"¿Qué es un CDN (Content Delivery Network)?", options:["Una red de bases de datos relacionales, concepto diferente al que se describe en esta pregunta","Una red global de servidores distribuidos geográficamente que cachean y sirven contenido estático (imágenes, CSS, JS) desde el nodo más cercano al usuario","Un proveedor de nombres de dominio, concepto diferente al que se describe en esta pregunta","Un tipo de cable de fibra óptica, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Servicios como Cloudflare o AWS CloudFront reducen drásticamente la latencia y la carga en el servidor de origen.", noShuffle:false },
  { concept_id:"dwes_u9_q29", unit:9, question:"¿Qué ventaja ofrece precompilar las plantillas y rutas de un framework PHP antes del despliegue en producción?", options:["Ocupan menos espacio en Git, concepto diferente al que se describe en esta pregunta","Elimina la sobrecarga de parsear y compilar archivos en tiempo de ejecución para cada visita de usuario, aumentando sustancialmente la velocidad de respuesta","Permite usar CSS moderno, concepto diferente al que se describe en esta pregunta","Evita usar bases de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Comandos como 'php artisan route:cache' o 'view:cache' serializan las estructuras en arrays planos de PHP de carga instantánea.", noShuffle:false },
  { concept_id:"dwes_u9_q30", unit:9, question:"¿Qué es la herramienta 'composer audit' introducida en Composer 2.4+?", options:["Un formateador de código, concepto diferente al que se describe en esta pregunta","Un escáner de seguridad que comprueba si los paquetes instalados en el proyecto tienen vulnerabilidades de seguridad conocidas en la base de datos de advisories","Un medidor de velocidad, concepto diferente al que se describe en esta pregunta","Un linter de sintaxis, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite detectar librerías comprometidas en el pipeline de integración continua antes de desplegar a producción.", noShuffle:false },
  { concept_id:"dwes_u9_q31", unit:9, question:"¿Qué significa el concepto 'Infrastructure as Code' (IaC)?", options:["Escribir código sin hardware, concepto diferente al que se describe en esta pregunta","Gestionar y aprovisionar servidores, redes y entornos mediante archivos de configuración legibles y versionables en lugar de configuración manual","Guardar código en la nube, concepto diferente al que se describe en esta pregunta","Comprar servidores por internet es una accion que no define correctamente este concepto"], correct:1, explanation:"IaC garantiza que los entornos sean perfectamente reproducibles, auditables e inmunes a la deriva de configuración humana.", noShuffle:false },
  { concept_id:"dwes_u9_q32", unit:9, question:"¿Qué es el 'Canary Deployment'?", options:["Desplegar solo en servidores de las Islas Canarias, concepto diferente al que se describe en esta pregunta","Introducir una nueva versión desplegándola inicialmente solo para un porcentaje muy pequeño de usuarios reales para validar estabilidad antes del despliegue masivo","Desplegar aplicaciones de audio, concepto diferente al que se describe en esta pregunta","Un test de sonido, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Inspirado en los canarios de las minas: si la nueva versión produce errores inesperados, se detecta con impacto mínimo.", noShuffle:false },
  { concept_id:"dwes_u9_q33", unit:9, question:"¿Qué puerto escucha por defecto el servicio PHP-FPM en una conexión de socket TCP de red?", options:["80","443","9000","3306"], correct:2, explanation:"El puerto predeterminado de FastCGI en modo TCP es el 9000 (o alternativamente mediante sockets de dominio Unix /run/php/php.sock).", noShuffle:false },
  { concept_id:"dwes_u9_q34", unit:9, question:"¿Qué utilidad tiene la herramienta PHPStan o Psalm en un pipeline de despliegue?", options:["Ejecutar la base de datos, concepto diferente al que se describe en esta pregunta","Realizar análisis estático de código para encontrar errores de tipo","Formatear el código con espacios, concepto diferente al que se describe en esta pregunta","Comprimir archivos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El análisis estático detecta errores sutiles en tiempo de desarrollo o CI, elevando drásticamente la robustez del código.", noShuffle:false },
  { concept_id:"dwes_u9_q35", unit:9, question:"¿Qué es un 'Rollback' en el contexto de despliegues y migraciones?", options:["Rebobinar una cinta de backup, concepto diferente al que se describe en esta pregunta","El proceso de revertir la aplicación o la base de datos al estado o versión anterior inmediata tras detectar un error crítico en producción","Reiniciar el servidor web, concepto diferente al que se describe en esta pregunta","Borrar la base de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Tener un mecanismo automatizado de rollback es fundamental para minimizar el impacto de un despliegue defectuoso.", noShuffle:false },
  { concept_id:"dwes_u9_q36", unit:9, question:"¿Por qué es crítico ejecutar las migraciones de base de datos como un paso explícito en el pipeline de despliegue?", options:["Para no perder los estilos de la web, concepto diferente al que se describe en esta pregunta","Para que los cambios de estructura de tablas se apliquen de forma controlada y sincrónica con el nuevo código desplegado","Porque MySQL no admite migraciones automáticas, concepto diferente al que se describe en esta pregunta","Para reiniciar los IDs, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Asegura que las columnas o tablas requeridas por la nueva versión del código existan antes de que el tráfico empiece a ser atendido.", noShuffle:false },
  { concept_id:"dwes_u9_q37", unit:9, question:"¿Qué comando de Docker detiene y elimina todos los contenedores, redes y volúmenes de un proyecto?", options:["docker compose down -v","docker compose stop","docker kill all","docker remove"], correct:0, explanation:"'docker compose down -v' limpia por completo el entorno levantado, incluyendo los volúmenes de datos asociados.", noShuffle:false },
  { concept_id:"dwes_u9_q38", unit:9, question:"¿Qué es el archivo '.dockerignore'?", options:["Un archivo que borra imágenes de Docker, concepto diferente al que se describe en esta pregunta","Un archivo que especifica qué carpetas y ficheros (como node_modules","Un fichero para ignorar puertos, concepto diferente al que se describe en esta pregunta","Una lista de errores de Docker, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Reduce significativamente el tamaño del build context y acelera la construcción de imágenes, evitando subir archivos temporales.", noShuffle:false },
  { concept_id:"dwes_u9_q39", unit:9, question:"¿Qué métricas fundamentales de un servidor de aplicaciones web deben monitorizarse con herramientas como Prometheus o Grafana?", options:["El color del chasis del servidor, concepto diferente al que se describe en esta pregunta","Uso de CPU, memoria RAM, tasa de peticiones por segundo","El número de teclas pulsadas, concepto que se aplica en un contexto distinto","La versión de Git, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Estas métricas permiten detectar degradaciones de rendimiento de forma temprana antes de que causen caídas totales de servicio.", noShuffle:false },
  { concept_id:"dwes_u9_q40", unit:9, question:"¿Qué es un 'WAF' (Web Application Firewall) en la infraestructura de despliegue?", options:["Un cable de red seguro, concepto diferente al que se describe en esta pregunta","Un cortafuegos especializado que inspecciona el tráfico HTTP/HTTPS a nivel de aplicación para bloquear ataques como SQLi, XSS o bots maliciosos","Un analizador de código estático, concepto diferente al que se describe en esta pregunta","Un sistema de hosting, que aunque es una herramienta util, no corresponde a esta definicion"], correct:1, explanation:"Soluciones como Cloudflare WAF o AWS WAF filtran tráfico malicioso en el borde de la red antes de que alcance los servidores de aplicación.", noShuffle:false },
  { concept_id:"dwes_u9_q41", unit:9, question:"¿Qué significa el acrónimo TDD (Test-Driven Development)?", options:["Total Data Deployment, concepto diferente al que se describe en esta pregunta","Desarrollo Guiado por Pruebas: escribir primero el test automatizado que falla, luego el código mínimo para superarlo y finalmente refactorizar","Time Delay Duration, concepto diferente al que se describe en esta pregunta","Testing Direct Database, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"TDD sigue el ciclo Rojo-Verde-Refactorización garantizando alta cobertura de pruebas y diseño desacoplado desde el primer momento.", noShuffle:false },
  { concept_id:"dwes_u9_q42", unit:9, question:"¿Qué utilidad tiene la configuración de límites de memoria (memory_limit) en php.ini para un servidor en producción?", options:["Acelerar el disco, concepto diferente al que se describe en esta pregunta","Prevenir que un script individual con fugas de memoria o consultas monstruosas agote toda la RAM física del servidor, tumbando los demás procesos concurrentes","Reducir el tamaño de los archivos PHP, concepto diferente al que se describe en esta pregunta","Permitir conexiones ilimitadas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Fijar memory_limit (ej: 256M) acota el impacto de operaciones descontroladas salvaguardando la estabilidad de todo el sistema operativo.", noShuffle:false }
];
